// Active-thruster click: online routes a SET_ACTIVE_THRUSTER op (the
// server flips it and broadcasts; applySnapshot redraws). Solo flips
// the local rocket state directly, unchanged.
function onSetActiveThrusterClick(cardId) {
  if (_online) { submitOnlineOp({ kind: 'SET_ACTIVE_THRUSTER', cardId }); return; }
  setActiveThruster(cardId);
}

// Active-prospector click: same split as the thruster activator.
function onSetActiveProspectorClick(cardId) {
  if (_online) { submitOnlineOp({ kind: 'SET_ACTIVE_PROSPECTOR', cardId }); return; }
  setActiveProspector(cardId);
}

// Tear down the online layer so the page can leave a multiplayer game
// cleanly. Unsubscribes the WS relay, flips the shared online flag off,
// and clears the online module vars.
//
// NOTE: returning to the SOLO sandbox in the same page load is NOT
// fully handled here - the state modules were hydrated from the server
// snapshot, so they need to be reloaded from localStorage (each module
// re-reading its persisted save) before solo play resumes. That
// reload is the caller's responsibility (e.g. a full re-mount / reload);
// this teardown only detaches the online plumbing. Flagging, not solving.
export function unmountBrowseOnline() {
  if (_onlineOffWS) { try { _onlineOffWS(); } catch { /* ignore */ } _onlineOffWS = null; }
  if (_onlinePoll) { clearInterval(_onlinePoll); _onlinePoll = null; }
  _onlinePollMs = 0;
  _lastAuctionPhase = null;
  _eagerPollInFlight = false;
  setOnline(false);
  _online = false;
  _spectator = false;
  _onlineGameId = null;
  _onlineMe = null;
  _onlineToast = null;
  if (_onlineChatOff) { try { _onlineChatOff(); } catch { /* ignore */ } _onlineChatOff = null; }
  // Drop the cached conversation so the next room doesn't inherit it.
  _chatLog.length = 0;
  resetChatList(document.getElementById('mp-chat-list'));
  resetChatList(document.getElementById('mp-auction-chat-list'));
  _onlineMaps = null;
  _onlineSnapshot = null;
  _lastAppliedSeq = -1;
  if (_renderer) {
    try {
      _renderer.setMpRockets(null);
      _renderer.setSandboxRocketOffset(0);
      if (typeof _renderer.setFreighterUnit === 'function') _renderer.setFreighterUnit(null);
      if (typeof _renderer.setMpFreighters === 'function') _renderer.setMpFreighters(null);
      if (typeof _renderer.setBernalUnits === 'function') _renderer.setBernalUnits(null);
      if (typeof _renderer.setMpBernals === 'function') _renderer.setMpBernals(null);
    } catch { /* ignore */ }
  }
  const shell = document.querySelector('.browse-shell');
  if (shell) { shell.style.removeProperty('--me-color'); shell.classList.remove('has-me-color'); }
  _onlineBusy = false;
  _onlineRoom = null;
  _onlineLobbyId = null;
  _onlineLeave = null;
  // Tear down the auction overlay + drafts so nothing lingers when the
  // player returns to the lobby list.
  _bidDraft = '';
  _joinDraft = '';
  _auctionKey = null;
  _deckPickerOpen = false;
  const auctionOverlay = document.getElementById('mp-auction-overlay');
  if (auctionOverlay) auctionOverlay.remove();
  // Tear down the first-player handoff + end-of-game overlays too.
  const fpOverlay = document.getElementById('mp-first-player-overlay');
  if (fpOverlay) fpOverlay.remove();
  const goOverlay = document.getElementById('mp-game-over-overlay');
  if (goOverlay) goOverlay.remove();
  setMpTurnAction('gameover', null);
  _gameOverDismissed = false;
  // Tear down any open crew-pick wizard so it doesn't leak across
  // sessions when the player returns to the lobby list.
  const crewOverlay = document.querySelector('.crew-wizard-overlay');
  if (crewOverlay) crewOverlay.remove();
  const draftOverlay = document.getElementById('mp-crew-draft-overlay');
  if (draftOverlay) draftOverlay.remove();
  _crewWizardOpen = false;
  const banner = document.getElementById('mp-turn-banner');
  if (banner) {
    banner.hidden = true;
    banner.classList.remove('is-your-turn');
    banner.style.removeProperty('--mp-turn-color');
    banner.textContent = '';
  }
  syncMpTabVisibility();
}

// Reset every shared game-state module to a fresh solo new-game. The
// state modules are process-wide singletons, so without this an online
// game's hydrated state (rocket / hand / discs / factories / ...) bleeds
// straight into a "Sandbox (solo)" session. Called when starting a fresh
// sandbox so each session is self-contained. (Server-authoritative MP
// re-hydrates from its snapshot, so a reset there is harmless too.)
export function resetSoloGame() {
  const safe = (fn) => { try { fn(); } catch { /* module not ready */ } };
  safe(() => rocketClearStack());
  safe(() => clearActiveProspector());
  safe(() => clearHand());
  safe(() => clearBoostMarks());
  safe(() => resetLeoStack());
  safe(() => resetDiscs());
  safe(() => resetStacks());                 // outposts
  safe(() => resetGlory());
  safe(() => resetFactoriesAndColonies());
  safe(() => resetDecks(new Set()));         // full fresh shuffled decks
  safe(() => resetClock());
  safe(() => resetAqua());
  safe(() => setTankWater(0));
  // Rocket position / route / trail module-locals + their saves.
  _rocketSiteId = null;
  _plannedRoute = null;
  _rocketTrail = [];
  _moveSnapshot = null;
  setHazardousMove(false);
  try {
    localStorage.removeItem(STORAGE_ROCKET_SITE);
    localStorage.removeItem(STORAGE_ROCKET_TRAIL);
    localStorage.removeItem(STORAGE_ROCKET_ROUTE);
    localStorage.removeItem(STORAGE_PENDING_MOVE);
  } catch { /* private mode */ }
  if (_renderer) {
    safe(() => { _renderer.setRoute(null); _renderer.setRouteEndpoints(null, null); _renderer.setRocketTrail(null); });
  }
}

// Sandbox hand strip wiring: drop target, slot rendering, +
// the grabber bar that lets the user drag the strip up to see
// more cards. Card-click opens the inspect modal instead of
// removing the slot directly - Discard lives in the modal.
// Touch-device check used to toggle UI between the desktop
// hover-driven flow and the mobile tap-to-select flow. Reads
// the standardised CSS media queries so an external keyboard
// or external mouse on a tablet still resolves to "hover".
function isTouchDevice() {
  return window.matchMedia('(hover: none) and (pointer: coarse)').matches;
}

// On a phone, panning to a site / rocket / search result needs
// to land MUCH closer than the desktop default - the canvas is
// pixel-dense and a 4×-5× zoom leaves the target as a tiny dot.
// Every "find this thing on the map" call routes through here
// so the touch breakpoint can override in one place.
function locateZoom(desktopZoom = 4) {
  return isTouchDevice() ? 7 : desktopZoom;
}

let _handWired = false;
function wireHandStrip() {
  if (_handWired) return;
  _handWired = true;
  const strip    = document.getElementById('sandbox-hand');
  const host     = document.getElementById('sandbox-hand-cards');
  const countEl  = document.getElementById('hand-count');
  const grabber  = document.getElementById('hand-grabber');
  if (!strip || !host) return;

  const lookup = (id) => PATENTS_BY_ID[id]
    || CREW.find((c) => c.id === id) || null;
  const kindOf = (id) =>
    CREW.some((c) => c.id === id) ? 'crew' : 'patent';

  // Drag from the deck → drop onto the strip → append slot.
  // preventDefault unconditionally on dragover - dataTransfer
  // .types is normalised differently across browsers and the
  // "includes" check was silently rejecting valid drags in
  // Firefox + Safari. The drop handler still validates the
  // payload before mutating state.
  host.addEventListener('dragover', (e) => {
    e.preventDefault();
    e.dataTransfer.dropEffect = 'move';
    host.classList.add('is-drop-target');
  });
  host.addEventListener('dragleave', () => host.classList.remove('is-drop-target'));
  host.addEventListener('drop', (e) => {
    e.preventDefault();
    host.classList.remove('is-drop-target');
    const id = e.dataTransfer.getData('text/card-id');
    const card = id && lookup(id);
    if (!card) return;
    // Card Market mode locks the library to browse-only;
    // patents must be acquired via Research Auction. Flash the
    // strip red, surface the rule.
    if (getMarketMode() === MARKET_MODE.MARKET) {
      host.classList.add('flash-error');
      setTimeout(() => host.classList.remove('flash-error'), 700);
      setStatus('🃏 Card Market mode: drag-to-hand is disabled. Open the 🛒 Cart tab or use Research Auction at LEO.');
      return;
    }
    // Online (solo, Free Library): the server owns the hand, so route the pick
    // through BUY_CARD (free action, 0 cost) instead of a local-only add that
    // the next snapshot would wipe. The snapshot hydrates the hand.
    if (_online) {
      if (isInHand(card.id)) {
        host.classList.add('flash-error');
        setTimeout(() => host.classList.remove('flash-error'), 700);
        return;
      }
      addToHand(card);   // optimistic; BUY_CARD makes it authoritative
      submitOnlineOp({ kind: 'BUY_CARD', cardId: card.id, free: true });
      return;
    }
    const r = addToHand(card);
    if (!r.ok) {
      host.classList.add('flash-error');
      setTimeout(() => host.classList.remove('flash-error'), 700);
    }
  });

  // Grabber: drag vertically to resize the strip between a
  // collapsed default height (152px) and ~60% of viewport so
  // the player can audit a many-card hand without leaving the
  // sandbox view.
  if (grabber) wireHandGrabber(grabber, strip);

  const repaintHand = () => {
    const slots = getHandSlots();
    host.innerHTML = '';
    if (countEl) countEl.textContent =
      `${slots.length} card${slots.length === 1 ? '' : 's'}`;
    slots.forEach((id, idx) => {
      const card = lookup(id);
      if (!card) return;
      const wrap = document.createElement('div');
      wrap.className = 'hand-slot';
      if (isBoostMarked(id)) wrap.classList.add('is-boost-marked');
      wrap.dataset.slotIdx = String(idx);
      const cardEl = renderCard(card, { type: kindOf(id) });
      wrap.appendChild(cardEl);

      // Quick-action row appended as a sibling of the card so
      // it CAN'T be clipped by .card's overflow:hidden when it
      // floats above the card top edge on hover. The slot's
      // 1.18 hover-scale carries both the card and this row so
      // they grow together. Positioning + reveal handled in
      // CSS via .hand-slot:hover.
      const quick = document.createElement('div');
      quick.className = 'hand-quick-actions';
      const qBtn = (cls, glyph, title, handler) => {
        const b = document.createElement('button');
        b.type = 'button';
        b.className = `hand-q ${cls}`;
        b.textContent = glyph;
        b.title = title;
        b.addEventListener('click', (ev) => { ev.stopPropagation(); handler(); });
        return b;
      };
      const discardQ = qBtn('q-discard', '🗑',
        'Discard (free, any number per turn)',
        () => discardHandCard(card, idx));
      quick.append(
        discardQ,
        // Free Market: effectively sells the card for +$3 (to the
        // bottom of its deck), via the shared op-gated confirm flow.
        qBtn('q-sell',    '💱', `Free Market: effectively sells this card to gain $${FREE_MARKET_AQUA} (costs 1 operation)`,
          () => freeMarketSellFromHand(card)),
        qBtn('q-produce', '🏭', `Exo produce (spectral ${card.spectralType || '?'})`,
          () => setStatus(`Exo-produce needs a Stage-3 factory matching spectral ${card.spectralType || '?'}.`)),
        qBtn('q-boost',   '🚀',
          isBoostable(card) ? (isBoostMarked(id) ? 'Unmark boost' : 'Mark for boost') : BOOST_BLOCKED_MSG,
          () => { if (!isBoostable(card)) { setStatus(BOOST_BLOCKED_MSG); return; } toggleBoostMark(id); }),
      );
      wrap.appendChild(quick);

      // Mobile-only "View" button. On touch devices we drop
      // the hover affordances (no hover on touch) and replace
      // them with a two-step tap: first tap selects the card
      // (raised + ring); second tap on the View button opens
      // the inspect modal. Prevents accidental modal-opens on
      // a casual fingerprint.
      const viewBtn = document.createElement('button');
      viewBtn.type = 'button';
      viewBtn.className = 'hand-view-btn';
      viewBtn.textContent = 'View';
      viewBtn.title = 'Open this card';
      viewBtn.addEventListener('click', (ev) => {
        ev.stopPropagation();
        openCardModal(card, kindOf(id), idx, { nav: { siblings: stackSiblings(slots), index: idx } });
      });
      wrap.appendChild(viewBtn);

      wrap.addEventListener('click', (ev) => {
        if (ev.target.closest('.card-flip, .card-rotate, .hand-q, .hand-view-btn')) return;
        if (isTouchDevice()) {
          // Tap toggles selection. Only one slot selected at a time.
          const wasSelected = wrap.classList.contains('is-selected');
          host.querySelectorAll('.hand-slot.is-selected').forEach((s) =>
            s.classList.remove('is-selected'));
          if (!wasSelected) wrap.classList.add('is-selected');
        } else {
          openCardModal(card, kindOf(id), idx, { nav: { siblings: stackSiblings(slots), index: idx } });
        }
      });
      host.appendChild(wrap);
    });
    repaintBoostCommit();
  };

  const commitBoost = async () => {
    const marked = getBoostMarked();
    if (!marked.length) return;
    // Variant cargo flow (user, 2026-05-24): Boost moves cards
    // Hand -> LEO Stack (NOT directly onto the rocket). The
    // rocket loads from LEO via the free Transfer action when
    // parked at LEO. Boost can always fire; there is no rocket-
    // location gate.
    //
    // LEO Stack is cards-only - it has no water tank (the Aqua
    // Bank already lives at LEO), so there is no wet-mass /
    // spillage concern here. Cards just move across.
    //
    // Boost costs Aqua = the total mass of the boosted cards
    // (user, 2026-05): the player confirms the spend before any
    // money moves. Rulebook I4: Boost is also one Operation per
    // turn (the multi-card batch counts as one op).
    const cards = marked.map((id) => lookup(id)).filter(Boolean);
    if (!cards.length) return;
    const have = getAqua();
    const n = cards.length;
    // A radiator's deployed side changes its mass (heavy is heavier), and boost
    // cost IS total mass - so the cheapest possible spend is every radiator on
    // its light side. If even that exceeds the bank, no side choice can afford it.
    const minCost = cards.reduce((s, c) => s + boostMassOf(c, c.type === 'radiator' ? 'light' : undefined), 0);
    if (minCost > have) {
      await confirmModal({
        title: '💸 Not enough Aqua',
        body: `Boosting ${n} card${n === 1 ? '' : 's'} costs at least <strong>${minCost}</strong> Aqua `
          + `(total mass), but your bank holds only <strong>${have}</strong>.`,
        yes: 'OK', no: '',
      });
      return;
    }
    // Boost rides the raygun economy: the first boost of the turn spends the
    // operation, then any further boost this turn is free. Online reads the
    // turn's action history from the cached snapshot to label the cost. The
    // free-after-first rule is enforced server-side, so it applies to server
    // games; the solo sandbox still treats every boost as the operation.
    const continuedBoost = _online
      && _onlineSnapshot
      && Array.isArray(_onlineSnapshot.turnActions)
      && _onlineSnapshot.turnActions.some((a) => a && a.kind === 'BOOST');
    const opNote = continuedBoost
      ? 'You already boosted this turn, so this rides up free (no operation).'
      : 'The first boost spends your operation; keep boosting free for the rest of the turn.';
    const res = await openBoostModal({ cards, have, opNote, boostTargets: anchoredBoostTargets() });
    if (!res.ok) return;
    const radSides = res.radSides || {};
    const cost = res.cost | 0;   // final spend reflects each radiator's chosen side
    // Online: the BOOST is a server op. Submit the marked ids + each radiator's
    // chosen deployed side; the server moves Hand -> LEO, charges aqua, spends
    // the op, locks the side, and broadcasts. Skip the local mutation below -
    // the snapshot re-hydrate is the source of truth (and other players see it).
    if (_online) {
      // M2: a boosted Bernal establishes a colony stack - pick its figure
      // (Kalpana / Stanford) now, at creation. One prompt per Bernal boosted.
      const figures = {};
      for (const id of marked) {
        const c = lookup(id);
        if (c && c.type === 'bernal' && isM2()) figures[id] = await chooseBernalFigure(c);
      }
      const sent = await submitOnlineOp({ kind: 'BOOST', cardIds: marked, radSides, figures, to: res.to });
      if (sent) { clearBoostMarks(); await offerBoostTransfer(marked); }
      return;
    }
    // Charge the Aqua first (affordability pre-checked above;
    // spendAqua is defence-in-depth). Then secure the op - if
    // none is left, refund the Aqua so the player isn't charged
    // for a boost that didn't happen.
    if (!spendAqua(cost)) {
      setStatus(`Boost aborted - not enough Aqua (need ${cost}).`);
      return;
    }
    if (!requireOp('Boost')) {
      addAqua(cost);
      return;
    }
    for (const id of marked) {
      const card = lookup(id);
      if (!card) continue;
      // Lock the radiator's chosen deployed side into the LEO slot at boost.
      const radSide = card.type === 'radiator' ? (radSides[id] || 'light') : undefined;
      addCardToLeo({ id, kind: kindOf(id), radSide });
      removeFromHand(id);
    }
    clearBoostMarks();
    setStatus(`🛰 Boosted <strong>${n}</strong> card${n === 1 ? '' : 's'} to LEO for <strong>${cost}</strong> Aqua. Bank: <strong>${getAqua()}</strong>.`);
    // Open the LEO inspector so the player sees the cards land
    // in LEO Stack. They'll Transfer LEO->Rocket separately
    // when the rocket is parked at LEO.
    openLeoStackModal();
  };
  const commitBtn = document.getElementById('hand-boost-commit');
  if (commitBtn) commitBtn.addEventListener('click', commitBoost);

  // "All cards" overview button in the hand header: a read-only audit of every
  // card the player owns, grouped by location (Hand / LEO / Rocket / Outposts)
  // with each location's water and glory chits.
  const handHeader = strip.querySelector('.hand-header');
  if (handHeader && !handHeader.querySelector('.hand-all-cards')) {
    const allBtn = document.createElement('button');
    allBtn.type = 'button';
    allBtn.className = 'hand-all-cards';
    allBtn.textContent = '📚 All cards';
    allBtn.title = 'Show every card you own, grouped by location';
    allBtn.addEventListener('click', () => {
      // Online: tint the header with my own seat colour + name.
      const me = (_online && _onlineMe && _onlineSnapshot)
        ? (_onlineSnapshot.players || []).find((p) => p.profileId === _onlineMe.id) : null;
      openAllCardsView({
        title: me ? '@' + me.name : 'All cards',
        titleColor: me ? me.color : null,
        locs: collectOwnedCardsLocal(),
      });
    });
    handHeader.appendChild(allBtn);
  }

  // The old #hand-stack-open and #hand-stack-locate top-level
  // buttons folded into the per-stack chips that the new
  // switcher renders below (each chip has its own 📍 pin); the
  // explicit listeners above are gone.

  repaintHand();
  onHandChange(repaintHand);

  // Stage-3 hand-bar stack switcher. Renders chips for LEO,
  // Rocket, and any active outposts. Re-renders on focus +
  // outpost change so newly-created outposts surface their
  // chip immediately and the focused chip stays highlighted.
  renderStackSwitcher();
  onFocusChange(renderStackSwitcher);
  onOutpostsChange(renderStackSwitcher);
  onRocketChange(renderStackSwitcher);
  onAquaChange(renderStackSwitcher);
  onHandChange(renderStackSwitcher);
  onFactoryChange(renderStackSwitcher);
  onColonyChange(renderStackSwitcher);
  onLeoChange(renderStackSwitcher);
}

// Render the hand-bar stack switcher. ALWAYS shows 6 buttons
// (LEO, Rocket, Outpost A/B/C/D); empty outpost slots stay
// visible but disabled. Each button is paired with a 📍 find-
// pin that flies the map to that stack without opening the
// modal - the old global Stack/Locate buttons fold into these
// per-stack controls.
//
// Click semantics:
//   - main button click  : focus this stack + open its inspector modal
//   - pin button click   : focus this stack + fly the map (no modal)
//   - empty outpost slot : the main button still opens a modal
//                          explaining how to create one; the pin is
//                          disabled (nowhere to fly).
// Player notes + tags for a map location, pooled across ALL games. Opened from
// the site popup's notes button. Needs a signed-in profile + the live server;
// shows a gentle notice otherwise. Tags are player-driven (quick-picks plus any
// custom tag); messages are free text. Everything is shared with every player.
function openSiteNotesModal(siteId, siteName) {
  document.querySelector('.site-notes-overlay')?.remove();
  const overlay = document.createElement('div');
  overlay.className = 'card-modal-overlay site-notes-overlay';
  overlay.tabIndex = -1;
  const close = () => { overlay.remove(); document.removeEventListener('keydown', onKey); };
  const onKey = (e) => { if (e.key === 'Escape') { e.preventDefault(); close(); } };
  document.addEventListener('keydown', onKey);
  overlay.addEventListener('click', (e) => { if (e.target === overlay) close(); });

  const dialog = document.createElement('div');
  dialog.className = 'site-notes-modal';
  dialog.innerHTML = `<div class="site-notes-head">
      <h3>🏷 Notes &middot; <span class="site-notes-loc"></span></h3>
      <button type="button" class="modal-x" title="Close (Esc)">×</button>
    </div>
    <div class="site-notes-body"><p class="muted">Loading…</p></div>`;
  dialog.querySelector('.site-notes-loc').textContent = siteName || siteId;
  dialog.querySelector('.modal-x').addEventListener('click', close);
  overlay.appendChild(dialog);
  document.body.appendChild(overlay);
  overlay.focus();

  const body = dialog.querySelector('.site-notes-body');
  const prof = activeProfile();
  const token = prof && prof.token;
  if (!apiAvailable() || !token) {
    body.innerHTML = '<p class="muted">Location notes need a signed-in profile and the live server. '
      + 'They are shared with every player across all games.</p>';
    return;
  }

  let state = { tags: [], messages: [] };
  const apply = (r) => {
    if (r && r.ok && r.data) { state = r.data; render(); }
    else body.innerHTML = '<p class="muted">Could not reach the notes service.</p>';
  };
  const refetch = async () => apply(await getSiteAnnotations(siteId, token));

  // "Server tags" = how the map-data SINGLE SOURCE OF TRUTH (data/node-tags.js)
  // classifies this node, plus the planner's flyby / radhaz, shown next to the
  // raw player tags so the two can be compared. An aerobrake node records
  // aerobrake + hazard here (a parachute is itself a kind of hazard), even
  // though its marker is just the parachute.
  const serverNode = (_activeData && _activeData.sites)
    ? _activeData.sites.find((s) => s.id2 === siteId) : null;
  const nt = NODE_TAGS[siteId];
  // Marker meanings (burn / hazard / aerobrake / lander-burn / flyby /
  // radiation), shared with the site popup so both read the same vocabulary.
  const labels = serverTagLabels(serverNode || { id2: siteId });
  // A node's synodic season: it can only be entered during that Sunspot phase.
  // Tinted with the same red / yellow / blue the map uses for season lanes.
  const SEASON_COLORS = { red: '#ef4444', yellow: '#facc15', blue: '#60a5fa' };
  const serverChipParts = labels.map((l) => {
    const info = tagInfo(l);
    return `<span class="site-tag-chip is-server" style="--tag:#8fa6d8"${info ? ` title="${esc(info)}"` : ''}><span class="site-tag-dot"></span>${esc(l)}</span>`;
  });
  if (nt && SEASON_COLORS[nt.season]) {
    serverChipParts.push(`<span class="site-tag-chip is-server" style="--tag:${SEASON_COLORS[nt.season]}" title="${esc(tagInfo(nt.season + ' season'))}"><span class="site-tag-dot"></span>${esc(nt.season)} season</span>`);
  }
  const serverChips = serverChipParts.length ? serverChipParts.join('') : '<span class="muted">none</span>';

  function render() {
    const tagChips = state.tags.map((t) => {
      const d = tagDisplay(t.tag);
      return `<button type="button" class="site-tag-chip${t.mine ? ' is-mine' : ''}" data-tag="${esc(t.tag)}" style="--tag:${esc(d.color)}" title="${t.mine ? 'Tap to remove your tag' : 'Tap to add this tag'}"><span class="site-tag-dot"></span>${esc(d.label)} <span class="site-tag-n">${t.count}</span></button>`;
    }).join('');
    const quick = SITE_TAGS.filter((t) => !state.tags.some((x) => x.tag === t.key)).map((t) =>
      `<button type="button" class="site-tag-pick" data-add="${esc(t.key)}" style="--tag:${esc(t.color)}"><span class="site-tag-dot"></span>${esc(t.label)}</button>`).join('');
    const msgs = state.messages.length ? state.messages.map((m) =>
      `<li><div class="site-msg-body">${esc(m.body)}</div><div class="site-msg-meta"><span class="player-name">${esc(m.author)}</span> · ${esc(new Date(m.createdAt).toLocaleDateString())}${m.mine ? ` <button type="button" class="site-msg-del" data-del="${m.id}">delete</button>` : ''}</div></li>`).join('')
      : '<li class="muted">No messages yet.</li>';
    body.innerHTML = `
      <div class="site-notes-sec">
        <h4>Server tags <span class="muted">(what the map data says)</span></h4>
        <div class="site-tags-row">${serverChips}</div>
      </div>
      <div class="site-notes-sec">
        <h4>Player tags <span class="muted">(tap yours to remove)</span></h4>
        <div class="site-tags-row">${tagChips || '<span class="muted">No tags yet.</span>'}</div>
        <h5>Add a tag</h5>
        <div class="site-tags-row site-tags-pick">${quick}</div>
        <div class="site-tag-custom"><input type="text" placeholder="custom tag" maxlength="24"><button type="button" class="modal-btn">Add</button></div>
      </div>
      <div class="site-notes-sec">
        <h4>Messages</h4>
        <ul class="site-msgs">${msgs}</ul>
        <div class="site-msg-post"><textarea rows="2" maxlength="500" placeholder="Leave a note for other players…"></textarea><button type="button" class="modal-btn primary">Post</button></div>
      </div>
      <p class="site-notes-foot muted">Shared with every player across all games.</p>`;
    body.querySelectorAll('.site-tag-chip').forEach((b) => b.addEventListener('click', async () => {
      const tag = b.getAttribute('data-tag');
      apply(b.classList.contains('is-mine')
        ? await removeSiteTag(siteId, tag, token)
        : await postSiteAnnotation(siteId, { kind: 'tag', tag, siteName }, token));
    }));
    body.querySelectorAll('.site-tag-pick').forEach((b) => b.addEventListener('click', async () => {
      apply(await postSiteAnnotation(siteId, { kind: 'tag', tag: b.getAttribute('data-add'), siteName }, token));
    }));
    const customIn = body.querySelector('.site-tag-custom input');
    const customAdd = async () => {
      const t = normaliseTag(customIn.value);
      if (!t) return;
      customIn.value = '';
      apply(await postSiteAnnotation(siteId, { kind: 'tag', tag: t, siteName }, token));
    };
    body.querySelector('.site-tag-custom .modal-btn').addEventListener('click', customAdd);
    customIn.addEventListener('keydown', (e) => { if (e.key === 'Enter') { e.preventDefault(); customAdd(); } });
    body.querySelectorAll('.site-msg-del').forEach((b) => b.addEventListener('click', async () => {
      apply(await deleteSiteAnnotation(siteId, Number(b.getAttribute('data-del')), token));
    }));
    const ta = body.querySelector('.site-msg-post textarea');
    body.querySelector('.site-msg-post .modal-btn').addEventListener('click', async () => {
      const text = ta.value.trim();
      if (!text) return;
      ta.value = '';
      apply(await postSiteAnnotation(siteId, { kind: 'message', body: text, siteName }, token));
    });
  }
  refetch();
}

function renderStackSwitcher() {
  const host = document.getElementById('hand-stack-switcher');
  if (!host) return;
  const focused = getFocusedStackId();
  const outposts = getOutposts();
  const rocketStack = getRocketStack();
  const rocketSite = getRocketSite();

  // Build one descriptor per stack slot. `siteAvailable` is what
  // the pin uses - false when there's no place to fly to (empty
  // outpost slot; rocket with no cards still has LEO as a sane
  // fallback, so we treat that as available).
  const slots = [
    {
      id: 'leo', icon: 'leo', sub: 'LEO',
      title: `LEO Stack - ${getLeoCards().length} card${getLeoCards().length === 1 ? '' : 's'}. Aqua bank: ${getAqua()}. Hand: ${getHandSlots().length} card${getHandSlots().length === 1 ? '' : 's'} (not yet boosted).`,
      siteAvailable: true,
      isEmpty: false,
    },
    {
      id: 'rocket', icon: 'rocket', sub: 'Rocket',
      title: rocketStack.length
        ? `Rocket - ${rocketStack.length} card${rocketStack.length === 1 ? '' : 's'}, ${Math.round(getTankWater() * 100) / 100} water${rocketSite ? `, at ${rocketSite.name}` : ', at LEO'}`
        : 'Rocket - empty (boost cards from hand to build the stack)',
      siteAvailable: true,
      isEmpty: false,
    },
  ];

  // M1 Freighter chip sits RIGHT AFTER the Rocket chip (the two movers side by
  // side), so the bar reads LEO / Rocket / Freighter / outposts. It is shown in
  // every M1 game but DISABLED (greyed, no map pin) until the big cube is in
  // play; the cube enters play by ET-Producing a Freighter card.
  {
    const fr = getMyFreighter();
    if (fr) {
      const cargoN = Array.isArray(fr.stack) ? fr.stack.length : 0;
      slots.push({
        id: 'freighter', icon: 'freighter', sub: 'Freighter',
        water: (fr.tank | 0) > 0,
        title: `Freighter${fr.promoted ? ' (promoted)' : ''} - ${cargoN} cargo, ${fr.tank | 0} water, at ${freighterLocLabel(fr)}`,
        siteAvailable: true,
        isEmpty: false,
      });
    } else if (_online && isM1()) {
      slots.push({
        id: 'freighter', icon: 'freighter', sub: 'Freighter',
        water: false,
        title: 'Freighter not in play yet - ET Produce a Freighter card at a Factory to launch your big cube.',
        siteAvailable: false,
        isEmpty: true,
      });
    }
  }

  // M2 Bernal chips: TWO dedicated colony slots (1st = Kalpana, 2nd = Stanford),
  // shown like the Freighter chip - each is a disabled placeholder until that
  // colony is established (by boosting a Bernal card), then it lights up and
  // opens that colony's stack modal. Each Bernal gets its own dedicated button.
  if (_online && isM2()) {
    const bernals = getMyBernals();
    const FIGS = [{ name: 'Kalpana', sub: 'K' }, { name: 'Stanford', sub: 'S' }];
    FIGS.forEach((fig, i) => {
      const bn = bernals[i];
      const glyph = `<span class="chip-bernal-glyph">\u{1F3D9}</span>`;
      if (bn) {
        const cargoN = Array.isArray(bn.stack) ? bn.stack.length : 0;
        const figName = bn.figure === 'stanford' ? 'Stanford' : 'Kalpana';
        slots.push({
          id: `bernal${i}`, glyphHtml: glyph, sub: fig.sub,
          water: (bn.tank | 0) > 0,
          title: `${figName} Bernal${bn.promoted ? ' (promoted)' : ''} - ${cargoN} cargo, ${bn.tank | 0} water, at ${bernalLocLabel(bn)}`,
          siteAvailable: !!bn.siteId,
          isEmpty: false,
        });
      } else {
        slots.push({
          id: `bernal${i}`, glyphHtml: glyph, sub: fig.sub,
          water: false,
          title: `${fig.name} Bernal not established yet - boost a Bernal card to establish your ${i === 0 ? 'first' : 'second'} colony.`,
          siteAvailable: false,
          isEmpty: true,
        });
      }
    });
  }

  for (const letter of ['A', 'B', 'C', 'D']) {
    const op = outposts[letter];
    if (op) {
      const opSite = _activeData?.byId?.[op.siteId];
      const factory = getFactory(op.siteId);
      const colony = getColony(op.siteId);
      const factoryTag = factory ? ` 🏭${factory.spectralType}` : '';
      const colonyTag  = colony  ? ' 🌐' : '';
      // 💧 on the chip when the outpost holds water, so a parked rocket
      // can tell at a glance there's fuel to pump.
      const hasWater = (op.tank | 0) > 0;
      slots.push({
        id: `outpost${letter}`, icon: 'outpost', water: hasWater, sub: letter,
        title: `Outpost ${letter} at ${opSite?.name || op.siteId} - ${op.cards.length} card${op.cards.length === 1 ? '' : 's'}, ${op.tank} water${factoryTag}${colonyTag}`,
        siteAvailable: !!opSite,
        isEmpty: false,
      });
    } else {
      slots.push({
        id: `outpost${letter}`, icon: 'outpost', sub: letter,
        title: `Outpost slot ${letter} is empty - convert a parked rocket here via 🚀→🏛`,
        siteAvailable: false,
        isEmpty: true,
      });
    }
  }

  // Small cyan droplet badge marking an outpost that holds water.
  const waterDot = '<svg class="chip-water" viewBox="0 0 24 24" width="11" height="11" aria-hidden="true">'
    + '<path d="M12 3 C12 3 19 12 19 17 A7 7 0 0 1 5 17 C5 12 12 3 12 3Z" fill="#52caf2" stroke="#d6f3ff" stroke-width="1.2"/></svg>';
  host.innerHTML = slots.map((s) => {
    const focusedClass = s.id === focused ? 'is-focused' : '';
    const emptyClass   = s.isEmpty ? 'is-empty' : '';
    return `<span class="hand-stack-group ${focusedClass} ${emptyClass}" data-stack="${esc(s.id)}">
      <button type="button" class="hand-stack-chip" title="${esc(s.title)}">
        <span class="chip-glyph">${s.glyphHtml || uiIcon(s.icon)}${s.water ? waterDot : ''}</span>
        <span class="chip-sub">${esc(s.sub)}</span>
      </button>
      <button type="button" class="hand-stack-pin" title="Fly map to ${esc(s.sub)}" ${s.siteAvailable ? '' : 'disabled'}>📍</button>
    </span>`;
  }).join('');

  host.querySelectorAll('.hand-stack-group').forEach((group) => {
    const id = group.getAttribute('data-stack');
    const chip = group.querySelector('.hand-stack-chip');
    const pin  = group.querySelector('.hand-stack-pin');
    if (chip) chip.addEventListener('click', () => focusAndOpenStack(id));
    if (pin)  pin.addEventListener('click',  () => focusAndFlyStack(id));
  });
}

// Focus a stack + open its inspector modal. Used by the chip
// click. Always sets focus, even if the stack is empty - the
// modal is the affordance that explains the empty state.
function focusAndOpenStack(id) {
  if (!id) return;
  // Only set focus when the slot can actually be focused (empty
  // outpost slots are not focusable per stacks.js#setFocusedStackId,
  // which rejects ids whose outpost doesn't exist). For empty
  // slots we still open the modal so the player learns how to
  // populate the slot.
  setFocusedStackId(id);
  openStackInspectorModal(id);
}

// Focus a stack + fly the map to its site. Used by the pin
// click - same as above but no modal.
function focusAndFlyStack(id) {
  if (!id) return;
  setFocusedStackId(id);
  flyToStack(id);
}

// Pan the map to the stack with the given id. LEO flies to
// LEO_ANCHOR; Rocket flies to the rocket's site (LEO when
// empty); an outpost flies to its site.
function flyToStack(id) {
  if (!_renderer) return;
  if (id === 'leo') {
    _renderer.flyTo(LEO_ANCHOR, locateZoom(4));
    return;
  }
  if (id === 'rocket') {
    const stack = getRocketStack();
    const site = stack.length ? getRocketSite() : null;
    if (site && Number.isFinite(site.x) && Number.isFinite(site.y)) {
      _renderer.flyTo(site, locateZoom(4));
    } else {
      _renderer.flyTo(LEO_ANCHOR, locateZoom(4));
    }
    return;
  }
  if (id === 'freighter') {
    const fr = getMyFreighter();
    if (!fr) return;
    const pid = getStackSiteId('freighter');
    const site = pid && _activeData?.byId?.[pid];
    if (site && Number.isFinite(site.x) && Number.isFinite(site.y)) {
      _renderer.flyTo(site, locateZoom(4));
    } else {
      _renderer.flyTo(LEO_ANCHOR, locateZoom(4));
    }
    return;
  }
  if (id && id.startsWith('outpost')) {
    const letter = id.slice('outpost'.length);
    const op = getOutpost(letter);
    if (!op || !_activeData) return;
    const site = _activeData.byId?.[op.siteId];
    if (site && Number.isFinite(site.x) && Number.isFinite(site.y)) {
      _renderer.flyTo(site, locateZoom(4));
    }
  }
}

// Fly the map to ANY player's rocket (used by the per-player pin in the mp
// roster). The player's rocket.siteId is a server slug (null = LEO); translate
// it to a planner node and pan there. Public info, so it works for every seat.
function flyToPlayerRocket(p) {
  if (!_renderer) return;
  const slug = p && p.rocket && p.rocket.siteId;
  const pid = slug ? toPlannerId(_onlineMaps, slug) : leoPlannerId();
  const pos = coordOfPlanner(pid);
  if (pos) _renderer.flyTo(pos, locateZoom(5));
  else _renderer.flyTo(LEO_ANCHOR, locateZoom(5));
}

// Stack inspector modal router. The Rocket case re-uses the
// existing full-featured openRocketStackModal; LEO and outposts
// get their own focused modals. Empty outpost slots get an
// affordance modal that explains how to populate the slot.
function openStackInspectorModal(id) {
  if (id === 'leo') { openLeoStackModal(); return; }
  if (id === 'rocket') { openRocketStackModal(); return; }
  if (id === 'freighter') { openUnifiedStackInspector('freighter'); return; }
  if (id && id.startsWith('bernal')) { openBernalUnitModal(Number(id.slice('bernal'.length)) || 0); return; }
  if (id && id.startsWith('outpost')) {
    const letter = id.slice('outpost'.length);
    const op = getOutpost(letter);
    if (op) openOutpostStackModal(letter);
    else    openEmptyOutpostModal(letter);
  }
}

// ====== Stack inspector shared helpers ======
//
// Every stack (LEO / Rocket / Outpost A-D) holds the same shape
// of cards. The inspector modals share a card-display + select
// + transfer pattern: render each card with the same renderCard
// the patent library uses, give each card a "Select" toggle,
// and offer one transfer button per colocated destination stack.

const STACK_LABELS = {
  leo:      { glyph: '🌍', sub: 'LEO',     name: 'LEO Stack' },
  rocket:   { glyph: '🚀', sub: 'Rocket',  name: 'Rocket' },
  outpostA: { glyph: '🏛', sub: 'A',       name: 'Outpost A' },
  outpostB: { glyph: '🏛', sub: 'B',       name: 'Outpost B' },
  outpostC: { glyph: '🏛', sub: 'C',       name: 'Outpost C' },
  outpostD: { glyph: '🏛', sub: 'D',       name: 'Outpost D' },
  freighter:{ glyph: '🚛', sub: 'Freighter', name: 'Freighter' },
  bernal0:  { glyph: '🏙', sub: 'Bernal 1', name: 'Bernal 1' },
  bernal1:  { glyph: '🏙', sub: 'Bernal 2', name: 'Bernal 2' },
};

// Where does a stack physically sit? Returns the siteId the
// stack is currently at, or null when the stack has no location
// (Hand is not a stack here; LEO is always at the LEO anchor).
function getStackSiteId(stackId) {
  if (stackId === 'leo') {
    // LEO Stack lives at the LEO anchor site. Return the LEO
    // site id (or 'leo' as a sentinel if _activeData isn't
    // ready yet).
    return getLeoSiteId();
  }
  if (stackId === 'rocket') {
    const site = getRocketSite();
    return site?.id || null;
  }
  if (stackId === 'freighter') {
    const fr = getMyFreighter();
    if (!fr) return null;
    if (fr.siteId == null) return getLeoSiteId();
    // Convert the server slug into the planner-id space the other stacks use,
    // the same translation hydrateOutposts applies, so colocation compares like
    // for like.
    return (_onlineMaps && toPlannerId(_onlineMaps, fr.siteId)) || fr.siteId;
  }
  if (stackId && stackId.startsWith('bernal')) {
    const bn = getMyBernals()[Number(stackId.slice('bernal'.length)) || 0];
    if (!bn) return null;
    if (bn.siteId == null) return getLeoSiteId();
    return (_onlineMaps && toPlannerId(_onlineMaps, bn.siteId)) || bn.siteId;
  }
  if (stackId && stackId.startsWith('outpost')) {
    const letter = stackId.slice('outpost'.length);
    const op = getOutpost(letter);
    return op?.siteId || null;
  }
  return null;
}

// Return the site id of the LEO anchor (the dedicated lagrange
// "LEO" node in the site data). Used by getStackSiteId for the
// LEO Stack and for colocated-destination math.
function getLeoSiteId() {
  if (!_activeData) return 'leo';
  const leo = _activeData.sites.find(
    (s) => s.type === 'lagrange' && s.name === 'LEO'
  );
  return leo?.id || 'leo';
}

// Cards owned by a stack. Returns the same { id, kind, face? }
// shape used everywhere.
function getStackCards(stackId) {
  if (stackId === 'leo')    return getLeoCards();
  if (stackId === 'rocket') return getRocketStack();
  if (stackId === 'freighter') {
    const fr = getMyFreighter();
    return (fr && Array.isArray(fr.stack)) ? fr.stack.slice() : [];
  }
  if (stackId && stackId.startsWith('bernal')) {
    const bn = getMyBernals()[Number(stackId.slice('bernal'.length)) || 0];
    return (bn && Array.isArray(bn.stack)) ? bn.stack.slice() : [];
  }
  if (stackId && stackId.startsWith('outpost')) {
    const letter = stackId.slice('outpost'.length);
    const op = getOutpost(letter);
    return op ? op.cards.slice() : [];
  }
  return [];
}

// Destinations the given source stack can transfer cards to
// RIGHT NOW. A destination is valid when it's a different stack
// at the SAME site (colocation rule G1). Returns an array of
// { id, label } objects; empty array when nothing's colocated.
// Two client (planner-id) sites count as colocated when a BUILT Space Elevator
// joins them (M1): cargo transfers across the elevator's ends. Mirrors the
// server's elevatorColocated. The elevator table + snapshot keys are server
// slugs, so convert both ends before the lookup.
function elevatorColocatedClient(plannerA, plannerB) {
  if (!_online || !isM1() || !plannerA || !plannerB || plannerA === plannerB) return false;
  const snap = _onlineSnapshot;
  if (!snap || !snap.elevators || !_onlineMaps) return false;
  const a = toServerId(_onlineMaps, plannerA);
  const b = toServerId(_onlineMaps, plannerB);
  return !!(a && b && snap.elevators[elevatorPairKey(a, b)]);
}
function getColocatedDestinations(sourceId) {
  const sourceSite = getStackSiteId(sourceId);
  if (!sourceSite) return [];
  const colo = (siteId) => siteId === sourceSite || elevatorColocatedClient(siteId, sourceSite);
  const dests = [];
  // LEO is always at LEO. If source is at LEO and not LEO
  // itself, LEO is a destination. Skip when source IS LEO.
  if (sourceId !== 'leo' && sourceSite === getLeoSiteId()) {
    dests.push({ id: 'leo', label: 'LEO Stack' });
  }
  // Rocket is a destination when:
  //  - it's colocated (its site matches the source site), loading
  //    the existing rocket, OR
  //  - the rocket stack is empty AND the source is an outpost: the
  //    first card transferred FORMS a new rocket at the outpost's
  //    site. (You can't form a new rocket while one is already
  //    active - the empty-stack check enforces "one rocket".)
  if (sourceId !== 'rocket') {
    const rs = getRocketSite();
    const rocketEmpty = getRocketStack().length === 0;
    if ((rs && colo(rs.id))
        || (rocketEmpty && sourceId.startsWith('outpost'))) {
      dests.push({ id: 'rocket', label: 'Rocket' });
    }
  }
  // Outposts at the same site (or an elevator-joined site). Skip the source.
  for (const letter of ['A', 'B', 'C', 'D']) {
    const opId = `outpost${letter}`;
    if (opId === sourceId) continue;
    const op = getOutpost(letter);
    if (op && colo(op.siteId)) {
      dests.push({ id: opId, label: `Outpost ${letter}` });
    }
  }
  // The Freighter unit, when it's colocated (load cargo into the big cube). Show
  // the cargo room (cards aboard / load limit) so a full or factory-only cube
  // reads at a glance.
  if (sourceId !== 'freighter' && getMyFreighter() && colo(getStackSiteId('freighter'))) {
    const info = freighterLoadInfo();
    const label = info ? `Freighter (${info.aboard}/${info.limit})` : 'Freighter';
    dests.push({ id: 'freighter', label });
  }
  // Bernal colony stacks, when colocated (a Bernal is a full stack - cards move
  // both ways between it and any colocated stack).
  getMyBernals().forEach((bn, i) => {
    const bid = `bernal${i}`;
    if (sourceId !== bid && bn && colo(getStackSiteId(bid))) {
      dests.push({ id: bid, label: `${bn.figure === 'stanford' ? 'Stanford' : 'Kalpana'} Bernal` });
    }
  });
  return dests;
}

// Move ONE card by id from sourceStack to destStack. Returns
// true on success. Wet-mass clamps re-apply on the destination
// after the move; any spilled water is logged. Used by the
// transfer section's "Send selected" button.
// Online batch transfer: submit ALL selected cards in ONE TRANSFER op.
// Returns true if it handled the click (online), false to fall through
// to the solo per-card loop. Fixes "only one card at a time" - the
// per-card loop fired N submitOnlineOps but _onlineBusy dropped every
// one after the first. LEO<->Rocket only; other combos toast.
function transferSelectedOnline(sourceId, destId, ids) {
  if (!_online) return false;
  // Loading the freighter: pre-check the same rules the server enforces (load
  // limit, Factory-Loading-Only) so a blocked load tells the player WHY instead
  // of looking like nothing happened. The server stays authoritative.
  if (destId === 'freighter') {
    const block = freighterTransferBlock((ids || []).length);
    if (block) { _onlineToast(block, 'error'); return true; }
  }
  // The server understands leo / rocket / outpostX as endpoints and validates
  // colocation, so ANY two colocated stacks can trade (outpost <-> outpost,
  // LEO <-> rocket, outpost <-> rocket, ...).
  submitOnlineOp({ kind: 'TRANSFER', cardIds: [...ids], from: sourceId, to: destId });
  return true;
}

function transferOneCard(sourceId, destId, cardId) {
  // Online: LEO <-> Rocket transfers map to the server TRANSFER op
  // (valid only while the rocket is parked at LEO; the server enforces
  // that). Fire-and-forget - the broadcast / poll snapshot re-hydrates
  // the stacks and repaints the open inspector. Return false so the
  // local move below is skipped. Other combos (outpost <-> *) have no
  // server op yet, so they toast rather than mutating local state the
  // next snapshot would clobber.
  //
  // NB: LEO -> Rocket is NOT BUILD_ROCKET - that op pulls from the
  // hand. The crew PICK_CREW staged in LEO lives in player.leo, so it
  // must travel via TRANSFER.
  if (_online) {
    // Any colocated stack-to-stack move. The server validates colocation and
    // forms the rocket at an outpost when empty.
    submitOnlineOp({ kind: 'TRANSFER', cardId, from: sourceId, to: destId });
    return false;
  }
  const TANK_MAX = 32;
  // Forming a rocket: an empty rocket stack adopts its location from
  // the first card transferred in from an outpost. Capture intent +
  // the previous site (for rollback) before mutating any stacks.
  const formingRocket = destId === 'rocket'
    && sourceId.startsWith('outpost')
    && getRocketStack().length === 0;
  const sourceSiteId = getStackSiteId(sourceId);
  const prevRocketSiteId = _rocketSiteId;
  // Pull the slot out of the source first so we know exactly
  // what we're moving (id + kind + face).
  let slot = null;
  if (sourceId === 'leo') {
    slot = removeCardFromLeoById(cardId);
  } else if (sourceId === 'rocket') {
    const stack = getRocketStack();
    const idx = stack.findIndex((s) => s.id === cardId);
    if (idx === -1) return false;
    slot = { ...stack[idx] };
    rocketRemoveCard(idx);
  } else if (sourceId.startsWith('outpost')) {
    const letter = sourceId.slice('outpost'.length);
    const op = getOutpost(letter);
    if (!op) return false;
    const idx = op.cards.findIndex((s) => s.id === cardId);
    if (idx === -1) return false;
    slot = op.cards[idx];
    removeCardFromOutpost(letter, idx);
  }
  if (!slot) return false;
  // Drop it into the destination.
  let added = false;
  if (destId === 'leo') {
    added = addCardToLeo(slot);
  } else if (destId === 'rocket') {
    // Place the (empty) rocket at the source site BEFORE adding the
    // card, so the onRocketChange sync that rocketAddCard fires
    // draws the sprite at the freshly-formed location.
    if (formingRocket && sourceSiteId) {
      _rocketSiteId = sourceSiteId;
      persistRocketSite();
    }
    added = rocketAddCard(slot.id, slot.kind, slot.face, slot.radSide) !== -1;
    if (!added && formingRocket) {
      _rocketSiteId = prevRocketSiteId;
      persistRocketSite();
    }
  } else if (destId.startsWith('outpost')) {
    const letter = destId.slice('outpost'.length);
    added = addCardToOutpost(letter, slot);
  }
  if (!added) {
    // Roll back to source on failure.
    if (sourceId === 'leo') addCardToLeo(slot);
    else if (sourceId === 'rocket') rocketAddCard(slot.id, slot.kind, slot.face, slot.radSide);
    else if (sourceId.startsWith('outpost')) {
      addCardToOutpost(sourceId.slice('outpost'.length), slot);
    }
    return false;
  }
  // Wet-mass clamp on the destination tank. Only the rocket
  // has a water tank; LEO + outposts that receive cards have
  // no spillage concern (LEO has no tank; outpost-tank clamps
  // would live in stacks.js if needed).
  if (destId === 'rocket') {
    const cap = Math.max(0, TANK_MAX - rocketStackDryMass());
    if (getTankWater() > cap) setTankWater(cap);
  }
  return true;
}

// Pull a single slot (by id) out of a stack, returning the
// removed { id, kind, face } or null. Mirrors transferOneCard's
// source-removal so decommission + transfer stay consistent.
function pullSlotFromStack(stackId, id) {
  if (stackId === 'leo') return removeCardFromLeoById(id);
  if (stackId === 'rocket') {
    const stack = getRocketStack();
    const idx = stack.findIndex((s) => s.id === id);
    if (idx === -1) return null;
    const slot = { ...stack[idx] };
    rocketRemoveCard(idx);
    return slot;
  }
  if (stackId.startsWith('outpost')) {
    const letter = stackId.slice('outpost'.length);
    const op = getOutpost(letter);
    if (!op) return null;
    const idx = op.cards.findIndex((s) => s.id === id);
    if (idx === -1) return null;
    const slot = { ...op.cards[idx] };
    removeCardFromOutpost(letter, idx);
    return slot;
  }
  return null;
}

// Put a slot back into its source stack (rollback when a
// decommission can't complete - e.g. crew, which never enters
// the hand).
function readdSlotToStack(stackId, slot) {
  if (stackId === 'leo') addCardToLeo(slot);
  else if (stackId === 'rocket') rocketAddCard(slot.id, slot.kind, slot.face, slot.radSide);
  else if (stackId.startsWith('outpost')) {
    addCardToOutpost(stackId.slice('outpost'.length), slot);
  }
}

// Decommission selected cards from a stack back to the player's
// hand (variant rule: voluntary stack removal returns cards to
// hand). Confirms first. Crew never enters the hand, so any crew
// in the selection is rolled back into the stack and reported.
async function decommissionSelectedToHand(stackId, ids, onDone) {
  const list = [...ids];
  if (!list.length) return;
  const ok = await confirmModal({
    title: '♻ Decommission to hand',
    body: `Return <strong>${list.length}</strong> selected card${list.length === 1 ? '' : 's'} `
      + `from this stack to your hand?`,
    yes: '♻ Decommission', no: 'Cancel',
  });
  if (!ok) return;
  // Online: decommission routes through the server so the hand actually gains
  // the cards (a local mutation would be clobbered by the next snapshot). The
  // server accepts rocket / LEO / outpost<L> as the source.
  if (_online) {
    const okOp = await submitOnlineOp({ kind: 'DECOMMISSION', cardIds: list, from: stackId });
    if (okOp) { try { onDone && onDone(); } catch (e) { /* ignore */ } }
    return;
  }
  let returned = 0;
  let blocked = 0;
  for (const id of list) {
    const slot = pullSlotFromStack(stackId, id);
    if (!slot) continue;
    const card = cardById(id);
    const r = card ? addToHand(card) : { ok: false };
    if (r && r.ok) returned++;
    else { readdSlotToStack(stackId, slot); blocked++; }
  }
  let msg = `♻ Decommissioned <strong>${returned}</strong> card${returned === 1 ? '' : 's'} to your hand.`;
  if (blocked) msg += ` <strong>${blocked}</strong> stayed (crew can't go to the hand).`;
  setStatus(msg);
  try { onDone && onDone(); } catch (e) { console.error('decommission onDone:', e); }
}

// LEO inspector. Same card-holder system as the rocket modal:
// each card is rendered via the shared renderCard() and gets a
// Select toggle so the player can mark cards for transfer. The
// transfer section at the bottom lists every colocated stack
// the player can ship the selected cards to. Free action - no
// op cost. Subscribes to onLeoChange / onRocketChange /
// onOutpostsChange so the modal re-renders live as state
// shifts.
// Fold a deployed radiator down to its light side (heavy -> light): hardier but
// less cooling, one-way. Online it's the SET_RADIATOR_SIDE op (the server finds
// the card in any of your stacks); solo mirrors it on the right state module.
// stackId is 'rocket' | 'leo' | 'outpost<L>'.
async function convertRadiatorToLight(stackId, cardId) {
  if (_online) {
    await submitOnlineOp({ kind: 'SET_RADIATOR_SIDE', cardId });
    return;
  }
  if (stackId === 'rocket') setRadiatorSide(cardId, 'light');
  else if (stackId === 'leo') setLeoRadiatorSide(cardId, 'light');
  else if (stackId && stackId.startsWith('outpost')) {
    setOutpostCardRadiatorSide(stackId.slice('outpost'.length), cardId, 'light');
  }
  setStatus('♨ Folded the radiator down to its light side (hardier, less cooling).');
}

function openLeoStackModal() {
  openUnifiedStackInspector('leo');
}

// Free Market (I3b) sale value for a Black-Side LEO card: the Exploitation
// Track stock price for its spectral type, driven by the GLOBAL count of that
// spectral's factories (the same shared math the server + scoring tab use).
function leoBlackSideValue(card) {
  const spec = (card && card.spectralType) || 'C';
  let n = 0;
  const facs = (_onlineSnapshot && _onlineSnapshot.factories) || {};
  for (const k in facs) { if (facs[k] && (facs[k].spectralType || 'C') === spec) n += 1; }
  return freeMarketBlackSideValue(n);
}

// My M1 Freighter unit from the live snapshot, or null. Online + M1 only (the
// server only ever sets player.freighter in an M1 game).
function getMyFreighter() {
  if (!_online || !_onlineSnapshot || !_onlineMe) return null;
  const me = (_onlineSnapshot.players || []).find((p) => p.profileId === _onlineMe.id);
  return (me && me.freighter) || null;
}
// Cargo state of my freighter, read off the INSTALLED face (mirrors the server's
// freighterLoadLimit / freighterFactoryOnly): how many cards are aboard, the
// load limit, whether the big cube is Factory-Loading-Only, and whether it's
// parked at one of my factories. Drives the transfer-room label + the can-load
// pre-check so a blocked transfer reads as a message, not a silent no-op.
function freighterLoadInfo() {
  const fr = getMyFreighter();
  if (!fr) return null;
  const card = cardById(fr.cardId);
  const face = fr.face === 'primary' ? 'primary' : 'secondary';
  const fd = (card && card.faces && card.faces[face]) || card || {};
  const limit = (fd.loadLimit != null ? fd.loadLimit : (card && card.loadLimit)) | 0;
  const aboard = (fr.stack || []).length;
  const factoryOnly = fd.factoryOnly != null ? !!fd.factoryOnly : !!(card && card.factoryOnly);
  const facs = (_onlineSnapshot && _onlineSnapshot.factories) || {};
  const atFactory = !!(fr.siteId && facs[fr.siteId]);
  return { card, face, limit, aboard, room: Math.max(0, limit - aboard), factoryOnly, atFactory };
}
// Reason (string) a freighter cannot take on `count` more cards right now, or
// null if it can. Mirrors the server's load_limit + factory_only checks so the
// client gives the player the same verdict immediately.
function freighterTransferBlock(count) {
  const info = freighterLoadInfo();
  if (!info) return null;
  if (info.factoryOnly && !info.atFactory) {
    return 'That freighter can only take on cargo while parked at a Factory.';
  }
  if (info.aboard + count > info.limit) {
    return `The freighter is at its cargo load limit (${info.aboard}/${info.limit}).`;
  }
  return null;
}
// My in-play Bernal colony units (up to 2: Kalpana then Stanford). Reads the
// snapshot the same way getMyFreighter does, so it's online-only (the Bernal
// unit lives in server state). Returns [] offline.
function getMyBernals() {
  if (!_online || !_onlineSnapshot || !_onlineMe) return [];
  const me = (_onlineSnapshot.players || []).find((p) => p.profileId === _onlineMe.id);
  return (me && Array.isArray(me.bernals)) ? me.bernals : [];
}
// Human-readable location of a Bernal unit (null siteId = LEO).
function bernalLocLabel(bn) {
  if (!bn || !bn.siteId) return 'LEO';
  const cid = (_onlineMaps && toPlannerId(_onlineMaps, bn.siteId)) || bn.siteId;
  const site = cid && _activeData && _activeData.byId && _activeData.byId[cid];
  return (site && site.name) || bn.siteId;
}
// Does a card's installed face carry an ISRU rig? Mirrors the server's
// slotHasIsruRig: patents carry isru in face.properties, crew on the face itself.
function cardFaceHasIsru(card, face) {
  if (!card) return false;
  const f = (card.faces && card.faces[face === 'secondary' ? 'secondary' : 'primary']) || card;
  if (!f) return false;
  if (Array.isArray(f.properties) && f.properties.some((p) => p && p.key === 'isru')) return true;
  return f.isru != null && Number.isFinite(Number(f.isru));
}
// Open the Bernal stack modal for an IN-PLAY unit (by index in getMyBernals()),
// passing its figure + face so the modal shows the right colony.
function openBernalUnitModal(index) {
  const bn = getMyBernals()[index];
  if (!bn) {
    setStatus('🏙 No colony in this Bernal slot yet. Boost a Bernal card from your hand to establish it.');
    return;
  }
  const card = cardById(bn.cardId);
  if (!card) return;
  const myTurn = _online && isOnlineMyTurn();
  const anchored = !!bn.anchored;
  // Offer "Stow in rocket" only when it can actually run: my turn, NOT anchored
  // (a fixed station can't be carried), no water aboard, and colocated with the
  // rocket (or the rocket is empty + forms here).
  const colo = getRocketStack().length === 0 || getStackSiteId(`bernal${index}`) === getStackSiteId('rocket');
  const canStow = myTurn && !anchored && !(bn.tank | 0) && colo;
  // Anchor costs the operation; Unanchor is free. Anchor needs an op in hand.
  const canAnchor = myTurn && !anchored && getOpsRemaining() > 0;
  const canUnanchor = myTurn && anchored;
  // Recall to hand: empty colony only (no cargo, no water). Stow in LEO: the
  // colony must be parked at LEO. Cargo transfers (both ways) need my turn.
  const cargoN = Array.isArray(bn.stack) ? bn.stack.length : 0;
  const canRecall = myTurn && !cargoN && !(bn.tank | 0);
  const canStowLeo = myTurn && !anchored && !(bn.tank | 0) && getStackSiteId(`bernal${index}`) === getLeoSiteId();
  const cargoSlots = Array.isArray(bn.stack) ? bn.stack : [];
  const cargo = cargoSlots.map((s) => ({ id: s.id, face: s.face, card: cardById(s.id) }));
  // Stack stats (parity with the rocket stack totals). A Bernal is a dirt
  // crawler: its active thruster IS the colony card, so thrust / fuel read off
  // the Bernal card's installed face; mass sums the card + cargo.
  const bnFace = (card.faces && card.faces[bn.face === 'secondary' ? 'secondary' : 'primary']) || card;
  const slotMass = (s) => {
    const c = cardById(s.id);
    const f = c && c.faces && c.faces[s.face === 'secondary' ? 'secondary' : 'primary'];
    return (((f && f.mass != null) ? f.mass : (c && c.mass)) | 0);
  };
  const slotRad = (s) => { const c = cardById(s.id); return (c && c.radHardness) | 0; };
  const dryMass = (bnFace.mass | 0) + cargoSlots.reduce((m, s) => m + slotMass(s), 0);
  const tank = bn.tank | 0;
  const wetMass = dryMass + tank;
  const rads = [bnFace.radHardness | 0, ...cargoSlots.map(slotRad)].filter((n) => n > 0);
  const stats = {
    cards: cargoSlots.length, dryMass, wetMass, tank,
    tankGrade: bn.tankGrade || 'dirt',
    thrust: bnFace.thrust != null ? bnFace.thrust : '-',
    fuel: bnFace.fuel != null ? bnFace.fuel : '-',
    minRad: rads.length ? Math.min(...rads) : '-',
  };
  // Fuel-tank opener for an IN-PLAY unit: reads the bernal FRESH each time and
  // wires the live fuel controls (scoop dirt / dump / transfer water). After any
  // fuel op resolves it reopens itself so the cylinder + strip repaint at the new
  // level. Parity with the rocket fuel tank's transfer controls.
  const openBernalFuel = () => {
    const cur = getMyBernals()[index];
    if (!cur) return;
    const curCard = cardById(cur.cardId);
    if (!curCard) return;
    const cFace = (curCard.faces && curCard.faces[cur.face === 'secondary' ? 'secondary' : 'primary']) || curCard;
    const cSlots = Array.isArray(cur.stack) ? cur.stack : [];
    const cDry = (cFace.mass | 0) + cSlots.reduce((m, s) => m + slotMass(s), 0);
    const cTank = Number(cur.tank) || 0;
    const cThrust = cFace.thrust != null ? cFace.thrust : null;
    const cGrade = cur.tankGrade === 'water' ? 'water' : 'dirt';
    const tankMax = getTankMax();
    let fc = null;
    if (myTurn) {
      const bnSite = getStackSiteId(`bernal${index}`);
      const atRealSite = !!bnSite && bnSite !== getLeoSiteId();
      const factoryHere = atRealSite && !!getFactory(bnSite);
      const isruAboard = cSlots.some((s) => cardFaceHasIsru(cardById(s.id), s.face));
      const canScoop = !cur.anchored && atRealSite && (factoryHere || isruAboard);
      const scoopReason = cur.anchored ? 'An anchored station does not crawl, so it can\'t scoop dirt.'
        : !atRealSite ? 'Park at a site (not LEO) to scoop dirt.'
        : 'Scooping dirt needs a factory here or an ISRU rig aboard the colony.';
      const transfers = getColocatedDestinations(`bernal${index}`)
        .filter((d) => d.id === 'rocket' || d.id.startsWith('outpost') || d.id.startsWith('bernal'))
        .map((d) => ({ id: d.id, label: d.label, icon: d.id === 'rocket' ? '🚀' : (d.id.startsWith('outpost') ? '🏛' : '🏙') }));
      // At LEO the colony can swap aqua with the bank 1:1, like the rocket (the
      // user: "it's in LEO, it should accept water from LEO bank").
      const atLeo = !!bnSite && bnSite === getLeoSiteId();
      const submitFuel = async (op) => { await submitOnlineOp(op); openBernalFuel(); };
      // Water capacity above the current fill, and the cashable/transferable
      // water on hand - used to resolve the "Max fill" / "Cash out" / "all"
      // step buttons into a concrete amount (the rocket fuel tank does the same).
      const waterRoom = Math.max(0, tankMax - cDry - cTank);
      const curWater = cGrade === 'water' ? Math.floor(cTank) : 0;
      // ONE delegated handler for every control button (the rocket's idiom):
      // act + amt ('1' | '5' | 'max' | 'all'), targets carried on pull:/send:.
      const onFuelAction = (act, amt) => {
        const n = (amt === 'max' || amt === 'all') ? null : (Number(amt) || 1);
        if (act === 'scoop') return submitFuel({ kind: 'DIRT_REFUEL', unit: `bernal${index}`, ...(n == null ? {} : { amount: n }) });
        if (act === 'dump') return submitFuel({ kind: 'DUMP', unit: `bernal${index}`, ...(n == null ? {} : { amount: n }) });
        if (act === 'aquaFill') { const a = n == null ? waterRoom : n; if (a > 0) return submitFuel({ kind: 'REFUEL', unit: `bernal${index}`, amount: a }); return; }
        if (act === 'aquaCash') { const a = n == null ? curWater : n; if (a > 0) return submitFuel({ kind: 'CASH_WATER', unit: `bernal${index}`, amount: a }); return; }
        if (act.startsWith('pull:')) { const a = n == null ? Math.max(1, waterRoom) : n; if (a > 0) return submitFuel({ kind: 'TRANSFER_FUEL', from: act.slice(5), to: `bernal${index}`, amount: a }); return; }
        if (act.startsWith('send:')) { const a = n == null ? curWater : n; if (a > 0) return submitFuel({ kind: 'TRANSFER_FUEL', from: `bernal${index}`, to: act.slice(5), amount: a }); return; }
      };
      fc = { myTurn: true, canScoop, scoopReason, transfers, atLeo, aqua: getAqua(), onFuelAction };
    }
    openBernalFuelTank({ dryMass: cDry, wetMass: cDry + cTank, tank: cTank, thrust: cThrust, tankMax, grade: cGrade, fuelControls: fc });
  };
  let handle = null;
  handle = openBernalStackModal(card, {
    kind: bn.figure === 'stanford' ? 'stanford' : 'kalpana',
    colour: _online ? myRocketColour() : 'gold',
    face: bn.face === 'secondary' ? 'secondary' : 'primary',
    unitIndex: index,
    anchored,
    cargo,
    stats,
    dryMass, wetMass,
    onOpenFuelTank: openBernalFuel,
    // Cargo transfer mounts the SAME select + send surface as the LEO Stack /
    // Outposts, INLINE inside this modal (not a second modal): mountStackTransfer
    // fills the cargo grid + Send footer for this Bernal's stack.
    mountTransfer: myTurn ? (cardsHost, footerHost, leadEl) => mountStackTransfer(
      cardsHost, footerHost, `bernal${index}`,
      {
        leadEl,
        onAfter: () => { if (handle && handle.close) handle.close(); },
        emptyCardsHtml: '<p class="muted">No cargo aboard.</p>',
        emptyDestsHint: 'Park beside the rocket or another stack here to transfer cargo.',
      }
    ) : null,
    onStow: canStow ? () => {
      submitOnlineOp({ kind: 'STOW_BERNAL', cardId: bn.cardId, to: 'rocket' });
      if (handle && handle.close) handle.close();
    } : null,
    onStowLeo: canStowLeo ? () => {
      submitOnlineOp({ kind: 'STOW_BERNAL', cardId: bn.cardId, to: 'leo' });
      if (handle && handle.close) handle.close();
    } : null,
    onRecall: canRecall ? () => {
      submitOnlineOp({ kind: 'DECOMMISSION', from: 'bernal-unit', cardId: bn.cardId });
      if (handle && handle.close) handle.close();
    } : null,
    onAnchor: canAnchor ? () => {
      submitOnlineOp({ kind: 'ANCHOR_BERNAL', cardId: bn.cardId });
      if (handle && handle.close) handle.close();
    } : null,
    onUnanchor: canUnanchor ? () => {
      submitOnlineOp({ kind: 'UNANCHOR_BERNAL', cardId: bn.cardId });
      if (handle && handle.close) handle.close();
    } : null,
  });
}
// Is `siteId` (a client planner id) a valid Promotion Site for a card needing
// colony `need` (a spectral letter or 'Push')? A colony dome must be present,
// and for a spectral need the factory there must match. Mirrors the server's
// colonyPromotes. 'Push' / unspecified accepts any colony.
function colonyPromotesAt(siteId, need) {
  if (!siteId || !getColony(siteId)) return false;
  if (!need || need === 'Push') return true;
  const f = getFactory(siteId);
  return !!(f && (f.spectralType || 'C') === need);
}
// Human-readable location for a freighter's server-slug siteId (null = LEO).
function freighterLocLabel(fr) {
  if (!fr || !fr.siteId) return 'LEO';
  const cid = (_onlineMaps && toPlannerId(_onlineMaps, fr.siteId)) || fr.siteId;
  const site = cid && _activeData && _activeData.byId && _activeData.byId[cid];
  return (site && site.name) || fr.siteId;
}
// My Factories that a Big Cube Swap could target: my own factories, excluding the
// one (if any) at the Freighter's own site (swapping with itself is rejected).
function mySwappableFactories() {
  const snap = _onlineSnapshot;
  if (!snap || !snap.factories || !_onlineMe) return [];
  const fr = getMyFreighter();
  const frSite = fr ? fr.siteId : null;
  const out = [];
  for (const sid in snap.factories) {
    const f = snap.factories[sid];
    if (f && f.ownerId === _onlineMe.id && sid !== frSite) {
      out.push({ siteId: sid, name: onlineSiteLabel(sid), spectralType: f.spectralType || 'C' });
    }
  }
  return out;
}
// Factory picker for the Big Cube Swap (1B8). Lists my factories; choosing one
// submits SWAP_BIG_CUBE and closes. onDone closes the freighter inspector behind it.
function openCubeSwapPicker(onDone) {
  document.querySelector('.cube-swap-overlay')?.remove();
  const facs = mySwappableFactories();
  const fr = getMyFreighter();
  const frHere = fr ? freighterLocLabel(fr) : '';
  const overlay = document.createElement('div');
  overlay.className = 'card-modal-overlay cube-swap-overlay';
  const close = () => { overlay.remove(); document.removeEventListener('keydown', onKey); };
  const onKey = (e) => { if (e.key === 'Escape') { e.preventDefault(); close(); } };
  document.addEventListener('keydown', onKey);
  overlay.addEventListener('click', (e) => { if (e.target === overlay) close(); });
  const dialog = document.createElement('div');
  dialog.className = 'mp-trade-builder-modal';
  dialog.style.maxWidth = '420px';
  dialog.innerHTML = `
    <div class="mp-trade-head">
      <h3>🔄 Swap big cube</h3>
      <button type="button" class="modal-x cube-swap-close" aria-label="Close">×</button>
    </div>
    <p class="muted" style="padding:2px 14px 6px">Pick a Factory to swap with. It moves to the Freighter's spot (<strong>${esc(frHere)}</strong>) and the Freighter takes the Factory's site. Free action.</p>
    <div class="mp-relocate-list" id="cube-swap-list"></div>`;
  overlay.appendChild(dialog);
  document.body.appendChild(overlay);
  dialog.querySelector('.cube-swap-close').addEventListener('click', close);
  const list = dialog.querySelector('#cube-swap-list');
  for (const f of facs) {
    const b = document.createElement('button');
    b.type = 'button';
    b.className = 'modal-btn mp-relocate-item mp-cube-row';
    b.innerHTML = `<span class="mp-cube-ic">🏭</span> ${esc(f.name)} <span class="industrialize-spectral-badge spectral-${esc(f.spectralType)}">${esc(f.spectralType)}</span>`;
    b.addEventListener('click', async () => {
      b.disabled = true;
      const ok = await submitOnlineOp({ kind: 'SWAP_BIG_CUBE', factorySiteId: f.siteId });
      if (ok) { close(); if (onDone) onDone(); } else { b.disabled = false; }
    });
    list.appendChild(b);
  }
}

// Outpost inspector. Same unified shape as the LEO modal.
// Adds factory / colony attachment chips in the stats row.
function openOutpostStackModal(letter) {
  openUnifiedStackInspector(`outpost${letter}`);
}

// M1 Freighter inspector: a read-only view of the player's big cube - the
// freighter card itself plus its cargo hold (Black-Side goods) and water.
// Cargo transfer / movement layer on in later increments; for now this gives
// the player the freighter "stack" in their stacks bar that they can inspect.
// Cargo capacity of the player's freighter (the installed face's load limit).
// Mirrors the server's freighterLoadLimit in engine.js.
function freighterCargoLimit() {
  const fr = getMyFreighter();
  if (!fr) return 0;
  const card = cardById(fr.cardId);
  if (!card) return 0;
  const face = fr.face === 'primary' ? 'primary' : 'secondary';
  const fd = card.faces && card.faces[face];
  if (fd && fd.loadLimit != null) return fd.loadLimit | 0;
  return (card.loadLimit | 0) || 0;
}

// The LEO / Outpost "select cards + send to a colocated stack" surface as a
// MOUNTABLE component, so the SAME select toggles + "Send N -> dest" footer can
// live inside the stack inspector OR inline inside the Bernal modal (no second
// modal - user 2026-06-28). It reuses the shared logic (getStackCards /
// getColocatedDestinations / transferSelectedOnline) AND the same .rocket-slot /
// .stack-inspector-* classes, so it reads + behaves identically wherever it's
// mounted.
//   cardsHost  - element filled with the selectable card grid
//   footerHost - element filled with the transfer footer (the Send buttons)
//   stackId    - 'leo' | 'rocket' | 'outpostX' | 'freighter' | 'bernalN'
//   opts.onAfter()        - fired after a send (e.g. close / refresh the host)
//   opts.emptyCardsHtml   - markup shown when the stack holds no cards
//   opts.emptyDestsHint   - muted hint shown when nothing is colocated
// Returns { selected, refresh }.
function mountStackTransfer(cardsHost, footerHost, stackId, opts = {}) {
  const selected = new Set();
  const syncFns = [];
  const refresh = () => {
    const n = selected.size;
    footerHost.querySelectorAll('.stack-inspector-xfer-btn').forEach((btn) => {
      btn.disabled = n === 0;
      btn.textContent = `Send ${n > 0 ? n + ' ' : ''}→ ${btn.dataset.destLabel || ''}`;
    });
  };
  const cards = getStackCards(stackId);
  const dests = getColocatedDestinations(stackId);

  cardsHost.innerHTML = '';
  // An optional read-only LEAD card (e.g. the Bernal colony card) sits as the
  // first cell of the SAME grid as the cargo, with no Select toggle.
  if (opts.leadEl) cardsHost.appendChild(opts.leadEl);
  if (!cards.length) {
    if (!opts.leadEl) {
      const empty = document.createElement('div');
      empty.innerHTML = opts.emptyCardsHtml || '<p class="muted">Nothing aboard.</p>';
      cardsHost.appendChild(empty.firstElementChild || empty);
    }
  } else {
    const sibs = stackSiblings(cards);
    let sibIdx = 0;
    for (const slot of cards) {
      const card = cardById(slot.id);
      if (!card) continue;
      const wrap = document.createElement('div');
      wrap.className = 'rocket-slot';
      const cardEl = renderCard(card, { type: slot.kind || 'patent', face: slot.face, radSide: slot.radSide || 'heavy' });
      makeCardViewable(cardEl, card, slot.kind || 'patent', slot.face, { siblings: sibs, index: sibIdx });
      sibIdx++;
      wrap.appendChild(cardEl);
      const actions = document.createElement('div');
      actions.className = 'rocket-slot-actions';
      const selBtn = document.createElement('button');
      selBtn.type = 'button';
      selBtn.className = 'rocket-select';
      const sync = () => {
        const on = selected.has(slot.id);
        wrap.classList.toggle('is-selected', on);
        selBtn.classList.toggle('is-on', on);
        selBtn.textContent = on ? '✓ Selected' : 'Select';
      };
      syncFns.push(sync);
      selBtn.addEventListener('click', () => {
        if (selected.has(slot.id)) selected.delete(slot.id); else selected.add(slot.id);
        sync(); refresh();
      });
      sync();
      actions.appendChild(selBtn);
      wrap.appendChild(actions);
      cardsHost.appendChild(wrap);
    }
  }

  footerHost.innerHTML = '';
  if (!dests.length) {
    footerHost.innerHTML = `
      <div class="stack-inspector-transfer empty">
        <h4>🔄 Transfer</h4>
        <p class="muted">${esc(opts.emptyDestsHint || 'No colocated stacks to transfer to right now. Park beside another stack to enable transfers.')}</p>
      </div>`;
  } else {
    const destButtonsHtml = dests.map((d) =>
      `<button type="button" class="stack-inspector-xfer-btn" data-dest="${esc(d.id)}" data-dest-label="${esc(d.label)}" disabled>Send → ${esc(d.label)}</button>`).join('');
    footerHost.innerHTML = `
      <div class="stack-inspector-transfer">
        <h4>🔄 Transfer (free action)</h4>
        <p class="muted">Select cards above, then send them to a colocated stack. Wet-mass clamps apply on the destination tank.</p>
        <div class="stack-inspector-selrow">
          <button type="button" class="modal-btn stack-selall">Select all</button>
          <button type="button" class="modal-btn stack-deselall">Deselect all</button>
        </div>
        <div class="stack-inspector-xfer-row">${destButtonsHtml}</div>
      </div>`;
    footerHost.querySelector('.stack-selall')?.addEventListener('click', () => {
      for (const slot of cards) selected.add(slot.id);
      for (const fn of syncFns) fn();
      refresh();
    });
    footerHost.querySelector('.stack-deselall')?.addEventListener('click', () => {
      selected.clear();
      for (const fn of syncFns) fn();
      refresh();
    });
    footerHost.querySelectorAll('.stack-inspector-xfer-btn').forEach((btn) => {
      btn.addEventListener('click', () => {
        const destId = btn.getAttribute('data-dest');
        if (!destId || selected.size === 0) return;
        // Online: one batch op for all selected cards (the snapshot re-hydrate
        // updates the board), then let the host close / refresh.
        if (transferSelectedOnline(stackId, destId, [...selected])) {
          selected.clear();
          if (typeof opts.onAfter === 'function') opts.onAfter();
          return;
        }
        const toMove = [...selected];
        let moved = 0;
        for (const cardId of toMove) {
          if (transferOneCard(stackId, destId, cardId)) { moved++; selected.delete(cardId); }
        }
        const destMeta = STACK_LABELS[destId] || { name: destId };
        const sourceMeta = STACK_LABELS[stackId] || { name: stackId };
        setStatus(`🔄 Transferred <strong>${moved}</strong> card${moved === 1 ? '' : 's'} from <em>${esc(sourceMeta.name)}</em> to <em>${esc(destMeta.name)}</em>.`);
        logAction({ type: 'transfer', icon: '🔄', summary: `Transferred ${moved} card${moved === 1 ? '' : 's'} from ${sourceMeta.name} to ${destMeta.name}`, undoable: false, data: { source: stackId, dest: destId, count: moved } });
        if (typeof opts.onAfter === 'function') opts.onAfter();
      });
    });
  }
  refresh();
  return { selected, refresh };
}

// Unified inspector for any non-rocket stack (LEO, Outpost
// A-D). The rocket modal stays separate (it has the thruster
// picker + prospector + afterburn UI) but we layer the same
// select-and-transfer pattern into it as well via
// renderRocketTransferSection.
function openUnifiedStackInspector(stackId) {
  document.querySelector('.stack-inspector-overlay')?.remove();
  const overlay = document.createElement('div');
  overlay.className = 'card-modal-overlay stack-inspector-overlay';
  const selected = new Set();
  let unsubFns = [];
  const close = () => {
    overlay.remove();
    document.removeEventListener('keydown', onKey);
    for (const fn of unsubFns) { try { fn(); } catch {} }
    unsubFns = [];
  };
  const onKey = (e) => { if (e.key === 'Escape') { e.preventDefault(); close(); } };
  document.addEventListener('keydown', onKey);
  overlay.addEventListener('click', (e) => { if (e.target === overlay) close(); });
  const dialog = document.createElement('div');
  dialog.className = 'stack-inspector-modal';
  overlay.appendChild(dialog);

  const render = () => {
    const labelMeta = STACK_LABELS[stackId] || { glyph: '?', sub: stackId, name: stackId };
    const cards = getStackCards(stackId);
    // Prune selections of cards that are no longer in this
    // stack (e.g. moved out by a sibling subscriber).
    for (const id of [...selected]) {
      if (!cards.some((c) => c.id === id)) selected.delete(id);
    }
    const dests = getColocatedDestinations(stackId);

    // Stat row depends on which stack we're inspecting.
    let statsHtml = '';
    if (stackId === 'leo') {
      const aqua = getAqua();
      const handCount = getHandSlots().length;
      statsHtml = `
        <div class="stack-inspector-stat-row">
          <div class="stack-inspector-stat"><span class="muted">LEO cards</span><strong>${esc(String(cards.length))}</strong></div>
          <div class="stack-inspector-stat"><span class="muted">Aqua bank</span><strong class="stat-aqua">${esc(String(aqua))} 💧</strong></div>
          <div class="stack-inspector-stat"><span class="muted">Hand (not at LEO)</span><strong>${esc(String(handCount))}</strong></div>
        </div>`;
    } else if (stackId.startsWith('outpost')) {
      const letter = stackId.slice('outpost'.length);
      const op = getOutpost(letter);
      if (!op) { close(); return; }
      const factory = getFactory(op.siteId);
      const colony  = getColony(op.siteId);
      const carriedChits = chitsOnOutpostCount(letter);
      statsHtml = `
        <div class="stack-inspector-stat-row">
          <div class="stack-inspector-stat"><span class="muted">Cards</span><strong>${esc(String(cards.length))}</strong></div>
          <div class="stack-inspector-stat"><span class="muted">Water FT</span><strong class="stat-water">${esc(String(op.tank))} 💧</strong></div>
          <div class="stack-inspector-stat"><span class="muted">Factory</span><strong>${factory ? `🏭 <span class="industrialize-spectral-badge spectral-${esc(factory.spectralType)}">${esc(factory.spectralType)}</span>` : '<span class="muted">none</span>'}</strong></div>
          <div class="stack-inspector-stat"><span class="muted">Colony</span><strong>${colony ? '🌐 dome' : '<span class="muted">none</span>'}</strong></div>
          ${carriedChits ? `<div class="stack-inspector-stat"><span class="muted">Glory chits</span><strong title="Carried by the crew stationed here; rides home for VP when they return to LEO">🎖 ${carriedChits}</strong></div>` : ''}
        </div>`;
    } else if (stackId === 'freighter') {
      const fr = getMyFreighter();
      if (!fr) { close(); return; }
      const lim = freighterCargoLimit();
      statsHtml = `
        <div class="stack-inspector-stat-row">
          <div class="stack-inspector-stat"><span class="muted">Cargo</span><strong>${esc(String(cards.length))} / ${esc(String(lim))}</strong></div>
          <div class="stack-inspector-stat"><span class="muted">Water</span><strong class="stat-water">${esc(String(fr.tank | 0))} 💧</strong></div>
          <div class="stack-inspector-stat"><span class="muted">Location</span><strong>${esc(freighterLocLabel(fr))}</strong></div>
        </div>
        <h4>Freighter</h4>
        <div class="rocket-stack-row fr-stack-row" id="freighter-unit-host"></div>`;
    } else if (stackId.startsWith('bernal')) {
      const idx = Number(stackId.slice('bernal'.length)) || 0;
      const bn = getMyBernals()[idx];
      if (!bn) { close(); return; }
      const fig = bn.figure === 'stanford' ? 'Stanford' : 'Kalpana';
      statsHtml = `
        <div class="stack-inspector-stat-row">
          <div class="stack-inspector-stat"><span class="muted">Cargo</span><strong>${esc(String(cards.length))}</strong></div>
          <div class="stack-inspector-stat"><span class="muted">Water</span><strong class="stat-water">${esc(String(bn.tank | 0))} 💧</strong></div>
          <div class="stack-inspector-stat"><span class="muted">Figure</span><strong>${esc(fig)}</strong></div>
          <div class="stack-inspector-stat"><span class="muted">Status</span><strong>${bn.anchored ? '⚓ anchored' : '🛰 mobile'}</strong></div>
        </div>`;
    }

    const headline = stackId === 'leo'
      ? '🌍 LEO Stack'
      : stackId === 'freighter'
        ? '🚛 Freighter'
        : stackId.startsWith('bernal')
          ? `🏙 Bernal ${(Number(stackId.slice('bernal'.length)) || 0) + 1}`
          : `🏛${esc(stackId.slice('outpost'.length))} - Outpost`;
    const locLabel = stackId === 'leo'
      ? 'orbital staging'
      : stackId === 'freighter'
        ? freighterLocLabel(getMyFreighter())
        : stackId.startsWith('bernal')
          ? (() => {
              const bn = getMyBernals()[Number(stackId.slice('bernal'.length)) || 0];
              const site = bn && _activeData?.byId?.[bn.siteId];
              return site?.name || (bn && bn.siteId) || 'LEO';
            })()
          : (() => {
              const letter = stackId.slice('outpost'.length);
              const op = getOutpost(letter);
              const site = _activeData?.byId?.[op?.siteId];
              return site?.name || op?.siteId || '';
            })();

    dialog.innerHTML = `
      <div class="stack-inspector-head">
        <h3>${headline}</h3>
        <span class="stack-inspector-loc">${esc(locLabel)}</span>
        <button type="button" class="modal-x stack-inspector-close" aria-label="Close" title="Close">×</button>
      </div>
      <div class="stack-inspector-body">
        ${statsHtml}
        <h4>Cards (${cards.length})</h4>
        <!-- Same #rocket-stack-cards container + .rocket-stack-row
             grid the rocket modal uses, so the cards render with
             identical look + spacing across every stack inspector. -->
        <div id="stack-inspector-cards">
          <div class="rocket-stack-row" id="stack-inspector-cards-row"></div>
        </div>
      </div>
      <!-- Footer: transfer + decommission + fuel + close all live
           in a pinned bar so they stay visible no matter how far
           the card list is scrolled. -->
      <div class="stack-inspector-footer">
        <div id="stack-inspector-transfer"></div>
        <div class="card-modal-actions">
          <button type="button" class="modal-btn decommission stack-decom-btn"
            title="Return the selected cards to your hand" disabled>♻ Decommission to hand</button>
          ${stackId === 'leo' && isLeoSite(getRocketSite())
            ? '<button type="button" class="modal-btn stack leo-fuel-tank" title="Open the docked rocket\'s water tank to transfer fuel">💧 Rocket fuel tank</button>'
            : ''}
          ${outpostPumpBtnHtml(stackId)}
          ${outpostFillBtnHtml(stackId)}
          ${outpostDissolveBtnHtml(stackId)}
        </div>
      </div>
    `;

    // Footer buttons depend on the selection count. refreshFooter
    // updates them IN PLACE so toggling Select never rebuilds the
    // card list (and so never resets its scroll position).
    const refreshFooter = () => {
      const n = selected.size;
      dialog.querySelectorAll('.stack-inspector-xfer-btn').forEach((btn) => {
        btn.disabled = n === 0;
        btn.textContent = `Send ${n > 0 ? n + ' ' : ''}→ ${btn.dataset.destLabel || ''}`;
      });
      const decom = dialog.querySelector('.stack-decom-btn');
      if (decom) {
        decom.disabled = n === 0;
        decom.textContent = `♻ Decommission to hand${n ? ` (${n})` : ''}`;
      }
    };

    const row = dialog.querySelector('#stack-inspector-cards-row');
    if (!cards.length) {
      row.innerHTML = '<p class="muted">Stack is empty.</p>';
    } else {
      // Swipe-browse siblings: counter bumped per resolved card, aligned with
      // stackSiblings' resolve order (handles duplicate cards in a stack).
      const sibs = stackSiblings(cards);
      let sibIdx = 0;
      for (const slot of cards) {
        const card = cardById(slot.id);
        if (!card) continue;
        // Same .rocket-slot wrapper + renderCard the rocket
        // modal uses - one design language across every stack.
        const wrap = document.createElement('div');
        wrap.className = 'rocket-slot';
        if (selected.has(slot.id)) wrap.classList.add('is-selected');
        const cardEl = renderCard(card, { type: slot.kind || 'patent', face: slot.face, radSide: slot.radSide || 'heavy' });
        makeCardViewable(cardEl, card, slot.kind || 'patent', slot.face, { siblings: sibs, index: sibIdx });
        sibIdx++;
        wrap.appendChild(cardEl);
        const actions = document.createElement('div');
        actions.className = 'rocket-slot-actions';
        const selBtn = document.createElement('button');
        selBtn.type = 'button';
        selBtn.className = 'rocket-select' + (selected.has(slot.id) ? ' is-on' : '');
        selBtn.textContent = selected.has(slot.id) ? '✓ Selected' : 'Select';
        selBtn.addEventListener('click', () => {
          const on = selected.has(slot.id);
          if (on) selected.delete(slot.id); else selected.add(slot.id);
          // Toggle in place - NO render() - so the card list's
          // scroll position is untouched.
          wrap.classList.toggle('is-selected', !on);
          selBtn.classList.toggle('is-on', !on);
          selBtn.textContent = !on ? '✓ Selected' : 'Select';
          refreshFooter();
        });
        actions.appendChild(selBtn);
        // Promotion (M1/M2): flip a GW thruster to its Purple-Side at a colony
        // dome whose factory matches the card's promotion colony. Shown on a
        // GW thruster slot in the rocket / an outpost when parked at a valid
        // Promotion Site. Online + M1 only; flips the card to its TW side.
        if (card.type === 'gw-thruster' && slot.face !== 'secondary' && _online && isM1()
            && (stackId === 'rocket' || stackId.startsWith('outpost'))
            && colonyPromotesAt(getStackSiteId(stackId), card.promotionColony)) {
          const promoBtn = document.createElement('button');
          promoBtn.type = 'button';
          promoBtn.className = 'rocket-select gw-promote';
          promoBtn.textContent = '🟣 Promote';
          const lockedPromo = !isOnlineMyTurn();
          promoBtn.disabled = lockedPromo;
          promoBtn.title = lockedPromo ? 'Wait for your turn.'
            : `Promote to its Purple-Side (TW thruster) at this ${card.promotionColony}-colony. Costs your operation.`;
          promoBtn.addEventListener('click', async () => {
            if (promoBtn.disabled) return;
            promoBtn.disabled = true;
            await submitOnlineOp({ kind: 'PROMOTE', cardId: slot.id, from: stackId });
            close();
          });
          actions.appendChild(promoBtn);
        }
        // A deployed radiator on its heavy side can be folded down to light
        // (hardier, less cooling) - one-way, mirroring the rad-damage flip.
        if (card.type === 'radiator' && (slot.radSide || 'heavy') !== 'light') {
          const foldBtn = document.createElement('button');
          foldBtn.type = 'button';
          foldBtn.className = 'rocket-select rad-fold-light';
          foldBtn.textContent = '♨ Fold to light';
          const lockedOnline = _online && !isOnlineMyTurn();
          foldBtn.disabled = lockedOnline;
          foldBtn.title = lockedOnline ? 'Wait for your turn.'
            : 'Fold this radiator to its light side: hardier (survives radiation) but less cooling. One-way.';
          foldBtn.addEventListener('click', async () => {
            if (foldBtn.disabled) return;
            foldBtn.disabled = true;
            await convertRadiatorToLight(stackId, slot.id);
          });
          actions.appendChild(foldBtn);
        }
        // Free Market (I3b): sell a Black-Side good from the LEO stack. It
        // returns to your hand and pays the Exploitation Track stock price for
        // its spectral type. Online only (server op); crew faces aren't goods.
        if (stackId === 'leo' && _online && slot.kind !== 'crew' && slot.face === 'secondary') {
          const sellVal = leoBlackSideValue(card);
          const sellBtn = document.createElement('button');
          sellBtn.type = 'button';
          sellBtn.className = 'rocket-select leo-free-market';
          sellBtn.textContent = `💱 Free Market (+${sellVal})`;
          const lockedSell = !isOnlineMyTurn();
          sellBtn.disabled = lockedSell;
          sellBtn.title = lockedSell
            ? 'Wait for your turn.'
            : `Sell this Black-Side ${card.spectralType || 'C'} good for ${sellVal} aqua (Exploitation Track price); the card returns to your hand. Costs your operation.`;
          sellBtn.addEventListener('click', async () => {
            if (sellBtn.disabled) return;
            sellBtn.disabled = true;
            await submitOnlineOp({ kind: 'FREE_MARKET', leoCardId: slot.id });
            close();
          });
          actions.appendChild(sellBtn);
        }
        wrap.appendChild(actions);
        row.appendChild(wrap);
      }
    }
    // Resolved glory chits live in the LEO stack as cards, shown on
    // their front or back side (back = a crew brought it home).
    if (stackId === 'leo') {
      const claimedChits = getClaimedChits();
      if (claimedChits.length) {
        if (!cards.length) row.innerHTML = '';
        for (const c of claimedChits) row.appendChild(buildChitToken(c.zone, { side: c.side, crewId: c.crewId }));
      }
    }

    // The Freighter unit card itself (the built freighter, not cargo): shown
    // above the cargo list, view-only (the unit can't be selected / transferred
    // like cargo).
    if (stackId === 'freighter') {
      const fr = getMyFreighter();
      const uhost = dialog.querySelector('#freighter-unit-host');
      const ucard = fr && cardById(fr.cardId);
      if (uhost && ucard) {
        const w = document.createElement('div');
        w.className = 'rocket-slot';
        const ce = renderCard(ucard, { type: 'patent', face: fr.face || 'secondary' });
        makeCardViewable(ce, ucard, 'patent', fr.face || 'secondary');
        w.appendChild(ce);
        const acts = document.createElement('div');
        acts.className = 'rocket-slot-actions';
        // Promotion (M1/M2): flip the Freighter to its Purple-Side at a colony
        // dome matching its promotion colony. Shown when parked at a valid
        // Promotion Site and not already promoted. Costs the operation.
        if (isM1() && !fr.promoted && fr.face !== 'secondary'
            && colonyPromotesAt(getStackSiteId('freighter'), ucard.promotionColony)) {
          const promoBtn = document.createElement('button');
          promoBtn.type = 'button';
          promoBtn.className = 'rocket-select gw-promote';
          promoBtn.textContent = '🟣 Promote';
          const lockedPromo = !isOnlineMyTurn();
          promoBtn.disabled = lockedPromo;
          promoBtn.title = lockedPromo ? 'Wait for your turn.'
            : `Promote the Freighter to its Purple-Side at this ${ucard.promotionColony}-colony. Costs your operation.`;
          promoBtn.addEventListener('click', async () => {
            if (promoBtn.disabled) return;
            promoBtn.disabled = true;
            await submitOnlineOp({ kind: 'PROMOTE', unit: 'freighter' });
            close();
          });
          acts.appendChild(promoBtn);
        }
        // Big Cube Swap (1B8): free action. A Promoted Freighter with no cargo or
        // glitch swaps its big cube with one of your Factory cubes (the Factory
        // moves to the Freighter's spot, the Freighter takes the Factory's site).
        if (_online && isM1() && (fr.promoted || fr.face === 'secondary')
            && !fr.glitched && !(Array.isArray(fr.stack) ? fr.stack.length : 0)
            && mySwappableFactories().length) {
          const swapBtn = document.createElement('button');
          swapBtn.type = 'button';
          swapBtn.className = 'rocket-select cube-swap';
          swapBtn.textContent = '🔄 Swap big cube';
          const lockedSwap = !isOnlineMyTurn();
          swapBtn.disabled = lockedSwap;
          swapBtn.title = lockedSwap ? 'Wait for your turn.'
            : 'Free action: swap the Freighter with one of your Factories. The Factory (with its colony + claim) moves to the Freighter\'s spot, and the Freighter takes the Factory\'s old site.';
          swapBtn.addEventListener('click', () => { if (!swapBtn.disabled) openCubeSwapPicker(close); });
          acts.appendChild(swapBtn);
        }
        // Stow (carry inside the rocket): the Freighter becomes a card in the
        // rocket stack with its cargo. Reverse it with "Convert to Freighter
        // stack" on the carried card. Needs colocation + an empty water tank.
        if (_online && isM1() && !fr.glitched && !(fr.tank | 0)) {
          const rocketEmpty = getRocketStack().length === 0;
          const colo = rocketEmpty || getStackSiteId('freighter') === getStackSiteId('rocket');
          if (colo) {
            const stowBtn = document.createElement('button');
            stowBtn.type = 'button';
            stowBtn.className = 'rocket-select';
            stowBtn.textContent = '📦 Stow in rocket';
            const lockedStow = !isOnlineMyTurn();
            stowBtn.disabled = lockedStow;
            stowBtn.title = lockedStow ? 'Wait for your turn.'
              : 'Carry the Freighter inside the rocket: it (and its cargo) ride as cards in the rocket stack. Convert it back to its own stack from the rocket.';
            stowBtn.addEventListener('click', async () => {
              if (stowBtn.disabled) return;
              stowBtn.disabled = true;
              await submitOnlineOp({ kind: 'STOW_FREIGHTER', to: 'rocket' });
              close();
            });
            acts.appendChild(stowBtn);
          }
        }
        // Recall to hand (free action): the big cube leaves the map and the
        // Freighter card returns to your hand, re-producible later at a Factory.
        // Needs an empty Freighter - no cargo aboard and an empty water tank.
        if (_online && isM1() && !fr.glitched) {
          const hasCargo = Array.isArray(fr.stack) ? fr.stack.length > 0 : false;
          const hasWater = (fr.tank | 0) > 0;
          const recallBtn = document.createElement('button');
          recallBtn.type = 'button';
          recallBtn.className = 'rocket-select';
          recallBtn.textContent = '♻️ Recall to hand';
          const lockedRecall = !isOnlineMyTurn();
          recallBtn.disabled = lockedRecall || hasCargo || hasWater;
          recallBtn.title = lockedRecall ? 'Wait for your turn.'
            : hasCargo ? 'Offload the Freighter\'s cargo first (transfer it to a colocated stack).'
            : hasWater ? 'Empty the Freighter\'s water tank first.'
            : 'Free action: bring the Freighter card back to your hand. The big cube leaves the map; produce it again at a Factory later.';
          recallBtn.addEventListener('click', async () => {
            if (recallBtn.disabled) return;
            recallBtn.disabled = true;
            await submitOnlineOp({ kind: 'DECOMMISSION', from: 'freighter-unit' });
            close();
          });
          acts.appendChild(recallBtn);
        }
        if (acts.children.length) w.appendChild(acts);
        uhost.appendChild(w);
      }
    }

    // Transfer section. Shown only when at least one
    // destination is colocated. The rule G1 covers card / FT
    // transfers between colocated stacks; this is the UI for
    // moving CARDS - water transfers stay on the existing fuel
    // modal for now (per-stack water move would be a future
    // unification).
    const transferHost = dialog.querySelector('#stack-inspector-transfer');
    if (dests.length === 0) {
      transferHost.innerHTML = `
        <div class="stack-inspector-transfer empty">
          <h4>🔄 Transfer</h4>
          <p class="muted">No colocated stacks to transfer to right now.${stackId === 'leo'
            ? ' Park the rocket at LEO to enable LEO ↔ Rocket transfers.'
            : ' Park the rocket at this site (or create a second outpost here) to enable transfers.'}</p>
        </div>`;
    } else {
      const destButtonsHtml = dests.map((d) =>
        `<button type="button" class="stack-inspector-xfer-btn" data-dest="${esc(d.id)}" data-dest-label="${esc(d.label)}" disabled>Send → ${esc(d.label)}</button>`
      ).join('');
      transferHost.innerHTML = `
        <div class="stack-inspector-transfer">
          <h4>🔄 Transfer (free action)</h4>
          <p class="muted">Select cards above, then send them to a colocated stack. Wet-mass clamps apply on the destination tank.</p>
          <div class="stack-inspector-selrow">
            <button type="button" class="modal-btn stack-selall">Select all</button>
            <button type="button" class="modal-btn stack-deselall">Deselect all</button>
          </div>
          <div class="stack-inspector-xfer-row">${destButtonsHtml}</div>
        </div>`;
      // Select-all / deselect-all over the source stack's cards.
      const selAll = transferHost.querySelector('.stack-selall');
      const deselAll = transferHost.querySelector('.stack-deselall');
      if (selAll) selAll.addEventListener('click', () => {
        for (const c of cards) selected.add(c.id);
        render();
      });
      if (deselAll) deselAll.addEventListener('click', () => {
        selected.clear();
        render();
      });
      transferHost.querySelectorAll('.stack-inspector-xfer-btn').forEach((btn) => {
        btn.addEventListener('click', () => {
          const destId = btn.getAttribute('data-dest');
          if (!destId || selected.size === 0) return;
          // Online: one batch op for all selected cards.
          if (transferSelectedOnline(stackId, destId, [...selected])) {
            selected.clear();
            return;
          }
          // Snapshot ids first - the source array mutates as
          // we move each card so iteration over `selected` is
          // safe via spread.
          const toMove = [...selected];
          let moved = 0;
          for (const cardId of toMove) {
            if (transferOneCard(stackId, destId, cardId)) {
              moved++;
              selected.delete(cardId);
            }
          }
          const destMeta = STACK_LABELS[destId] || { name: destId };
          const sourceMeta = STACK_LABELS[stackId] || { name: stackId };
          setStatus(`🔄 Transferred <strong>${moved}</strong> card${moved === 1 ? '' : 's'} from <em>${esc(sourceMeta.name)}</em> to <em>${esc(destMeta.name)}</em>.`);
          logAction({
            type: 'transfer',
            icon: '🔄',
            summary: `Transferred ${moved} card${moved === 1 ? '' : 's'} from ${sourceMeta.name} to ${destMeta.name}`,
            undoable: false,
            data: { source: stackId, dest: destId, count: moved },
          });
          render();
        });
      });
    }

    dialog.querySelector('.stack-inspector-close').addEventListener('click', close);
    // When the rocket is docked at LEO, a shortcut into its water
    // tank (the aqua <-> tank transfer UI lives there). Close the
    // LEO inspector first so the two modals don't stack / fight
    // over the Escape key.
    const fuelBtn = dialog.querySelector('.leo-fuel-tank');
    if (fuelBtn) {
      fuelBtn.addEventListener('click', () => {
        close();
        openFuelTankModal();
      });
    }
    // Pump the outpost's water into a colocated rocket.
    const pumpBtn = dialog.querySelector('.stack-pump-fuel');
    if (pumpBtn) {
      pumpBtn.addEventListener('click', () => {
        const letter = pumpBtn.dataset.letter;
        const max = Number(pumpBtn.dataset.max) || 0;
        if (max <= 0) return;
        close();
        doPumpOutpostFuel(letter, max);
      });
    }
    const fillBtn = dialog.querySelector('.stack-fill-fuel');
    if (fillBtn) {
      fillBtn.addEventListener('click', () => {
        const letter = fillBtn.dataset.letter;
        const max = Number(fillBtn.dataset.max) || 0;
        if (max <= 0) return;
        close();
        doPumpFuelToOutpost(letter, max);
      });
    }
    // Decommission an empty outpost (dissolve it, free the slot).
    const dissolveBtn = dialog.querySelector('.stack-dissolve-outpost');
    if (dissolveBtn) {
      dissolveBtn.addEventListener('click', async () => {
        const letter = dissolveBtn.dataset.letter;
        const op = getOutpost(letter);
        const waterNote = op && (op.tank | 0) > 0
          ? ` Its ${op.tank} water will be lost.` : '';
        const ok = await confirmModal({
          title: `🗑 Decommission Outpost ${letter}`,
          body: `Free outpost slot ${letter}?${waterNote}`,
          yes: '🗑 Decommission', no: 'Cancel',
        });
        if (!ok) return;
        if (_online) { await submitOnlineOp({ kind: 'DISSOLVE_OUTPOST', letter }); close(); return; }
        dissolveOutpost(letter);
        close();
      });
    }
    // Decommission: return the selected cards to hand (free,
    // any-time). Active only when something is selected.
    const decomBtn = dialog.querySelector('.stack-decom-btn');
    if (decomBtn) {
      decomBtn.addEventListener('click', () => {
        if (!selected.size) return;
        decommissionSelectedToHand(stackId, [...selected], render);
      });
    }
    // Initialise footer button states from the current selection.
    refreshFooter();
  };

  // Subscribe to every state change that could affect the
  // displayed cards or the colocated-destination list. The
  // modal re-renders in place so transfers feel instant.
  unsubFns.push(onLeoChange(render));
  unsubFns.push(onRocketChange(render));
  unsubFns.push(onOutpostsChange(render));
  unsubFns.push(onFactoryChange(render));
  unsubFns.push(onColonyChange(render));

  render();
  document.body.appendChild(overlay);
  overlay.focus();
}

// Empty-slot affordance modal. Explains how the player can
// populate the slot. Tells the player which other slots are
// occupied so they understand the constraint.
function openEmptyOutpostModal(letter) {
  document.querySelector('.stack-inspector-overlay')?.remove();
  const overlay = document.createElement('div');
  overlay.className = 'card-modal-overlay stack-inspector-overlay';
  const close = () => { overlay.remove(); document.removeEventListener('keydown', onKey); };
  const onKey = (e) => { if (e.key === 'Escape') { e.preventDefault(); close(); } };
  document.addEventListener('keydown', onKey);
  overlay.addEventListener('click', (e) => { if (e.target === overlay) close(); });
  const taken = Object.keys(getOutposts()).sort();
  const takenLabel = taken.length
    ? `Occupied slots: <strong>${taken.join(', ')}</strong>`
    : 'No outpost slots are occupied yet.';
  const dialog = document.createElement('div');
  dialog.className = 'stack-inspector-modal';
  dialog.innerHTML = `
    <div class="stack-inspector-head">
      <h3>🏛${esc(letter)} - Empty slot</h3>
      <button type="button" class="modal-x stack-inspector-close" aria-label="Close" title="Close">×</button>
    </div>
    <div class="stack-inspector-body">
      <p>Outpost slot <strong>${esc(letter)}</strong> isn't in use yet. To create an outpost in this slot:</p>
      <ol class="stack-inspector-howto">
        <li>Park your rocket at any non-LEO site with cards loaded.</li>
        <li>Open the site popup and tap <strong>🚀→🏛 Convert to Outpost</strong>.</li>
        <li>Pick slot <strong>${esc(letter)}</strong> from the picker.</li>
      </ol>
      <p class="muted">${takenLabel}</p>
      <p class="muted">
        ET Production at a player-owned factory can also create
        a fresh outpost when none exists at that site - the slot
        picker will offer this letter.
      </p>
    </div>
  `;
  overlay.appendChild(dialog);
  dialog.querySelector('.stack-inspector-close').addEventListener('click', close);
  document.body.appendChild(overlay);
  overlay.focus();
}

// Vertical resize grabber for the hand strip. Tracks a CSS
// variable on the strip element so the height is restored
// between repaints + survives onHandChange rerenders.
function wireHandGrabber(grabber, strip) {
  let startY = 0;
  let startH = 0;
  // Publish the live hand height as a CSS custom property on the
  // browse-shell so the sidepanel can stop its `bottom` at the
  // hand's top edge instead of overdrawing it.
  const shell = document.querySelector('.browse-shell');
  const publishHeight = (h) => {
    if (shell) shell.style.setProperty('--hand-height', `${h}px`);
  };
  publishHeight(strip.getBoundingClientRect().height || 320);
  const onMove = (clientY) => {
    const dy = startY - clientY;            // drag up = positive
    const next = Math.max(120, Math.min(window.innerHeight * 0.7, startH + dy));
    strip.style.height = `${next}px`;
    publishHeight(next);
  };
  const onPointerDown = (e) => {
    const cy = e.touches ? e.touches[0].clientY : e.clientY;
    startY = cy;
    startH = strip.getBoundingClientRect().height;
    document.body.style.userSelect = 'none';
    const moveEv = e.touches ? 'touchmove' : 'pointermove';
    const upEv   = e.touches ? 'touchend'  : 'pointerup';
    const onMoveEv = (ev) => onMove(ev.touches ? ev.touches[0].clientY : ev.clientY);
    const onUpEv   = () => {
      document.body.style.userSelect = '';
      document.removeEventListener(moveEv, onMoveEv);
      document.removeEventListener(upEv, onUpEv);
    };
    document.addEventListener(moveEv, onMoveEv);
    document.addEventListener(upEv, onUpEv);
  };
  grabber.addEventListener('pointerdown', onPointerDown);
  grabber.addEventListener('touchstart', onPointerDown, { passive: true });
}

// Modals + the drag-ghost append to the live overlay root, which
// is the fullscreen element when one is active (e.g. the user
// pressed ⛶ on the map toolbar) and document.body otherwise.
// Anything appended outside the fullscreen root is invisible
// while the Fullscreen API is engaged - so a modal mounted in
// body would just silently not show up. The watcher below
// re-parents any open overlays on fullscreenchange so they
// follow the user in / out of fullscreen too.
function overlayRoot() {
  return document.fullscreenElement || document.body;
}
function mountOverlay(el) {
  overlayRoot().appendChild(el);
  return el;
}
document.addEventListener('fullscreenchange', () => {
  const root = overlayRoot();
  // Move every known overlay class into the new root so a modal
  // that was open when the user toggled fullscreen stays visible.
  // Selectors cover the card / fuel-tank / rocket-stack /
  // confirm / hazard / turn-clock modals + the drag ghost.
  const selectors = [
    '.card-modal-overlay',
    '.fuel-tank-overlay',
    '.confirm-modal-overlay',
    '.rocket-stack-overlay',
    '.hazard-confirm-overlay',
    '.drag-ghost',
    '.card-tip',
  ];
  for (const sel of selectors) {
    for (const el of document.querySelectorAll(sel)) {
      if (el.parentNode !== root) root.appendChild(el);
    }
  }
});

// Custom drag-image. The browser's default drag-image is a
// faded snapshot of the element with no animation; we replace
// it with a fixed-position clone that follows the pointer, casts
// a heavy drop shadow, and wiggles with spring-damped rotation
// driven by horizontal velocity. The native HTML5 drop event
// still handles the actual data transfer - this only changes
// the visual the user sees while dragging.
let _dragGhost = null;
let _dragGhostState = null;

function startCustomDragGhost(srcEl, ev) {
  endCustomDragGhost();
  // 1×1 transparent canvas. setDragImage on a freshly-constructed
  // <img src=data:…> raced the browser in Safari + Firefox -
  // the drag started before the image loaded and the native
  // ghost flickered in. A canvas is fully painted synchronously
  // at the moment we hand it off, so the swap is reliable.
  const blank = document.createElement('canvas');
  blank.width = 1; blank.height = 1;
  try { ev.dataTransfer.setDragImage(blank, 0, 0); } catch { /* IE */ }

  const rect = srcEl.getBoundingClientRect();
  const ghost = srcEl.cloneNode(true);
  ghost.classList.add('drag-ghost');
  ghost.style.width  = rect.width + 'px';
  ghost.style.height = rect.height + 'px';
  // Anchor the ghost so the pointer "holds" the spot where the
  // user grabbed - feels less floaty than centring it.
  const offsetX = ev.clientX - rect.left;
  const offsetY = ev.clientY - rect.top;
  ghost.style.left = (ev.clientX - offsetX) + 'px';
  ghost.style.top  = (ev.clientY - offsetY) + 'px';
  mountOverlay(ghost);

  _dragGhost = ghost;
  _dragGhostState = {
    offsetX,
    offsetY,
    lastX: ev.clientX,
    lastY: ev.clientY,
    lastT: performance.now(),
    rotTarget: 0,
    rotCurrent: 0,
    raf: 0,
  };

  // Track pointer via document-level dragover (the only
  // drag-event with reliable clientX/clientY across browsers).
  document.addEventListener('dragover', onDragGhostMove);
  _dragGhostState.raf = requestAnimationFrame(animateDragGhost);
}

function onDragGhostMove(ev) {
  const s = _dragGhostState;
  if (!s || !_dragGhost) return;
  ev.preventDefault();   // also acts as dropEffect: copy
  const now = performance.now();
  const dt = Math.max(1, now - s.lastT);
  const vx = (ev.clientX - s.lastX) / dt;   // px/ms
  s.lastX = ev.clientX;
  s.lastY = ev.clientY;
  s.lastT = now;
  // Rotation target tilts toward the direction of horizontal
  // motion. Capped so a fast flick doesn't spin the card past
  // legibility. Wiggle comes from the spring lerp in animate().
  s.rotTarget = Math.max(-18, Math.min(18, vx * 28));
  _dragGhost.style.left = (ev.clientX - s.offsetX) + 'px';
  _dragGhost.style.top  = (ev.clientY - s.offsetY) + 'px';
}

function animateDragGhost() {
  const s = _dragGhostState;
  if (!s || !_dragGhost) return;
  // Critically-damped spring toward rotTarget. rotTarget decays
  // on its own so the rotation eases back to 0 when the user
  // pauses, giving the "wiggle settling" feel.
  s.rotCurrent += (s.rotTarget - s.rotCurrent) * 0.20;
  s.rotTarget *= 0.86;
  _dragGhost.style.transform = `translate3d(0,0,0) rotate(${s.rotCurrent.toFixed(2)}deg)`;
  s.raf = requestAnimationFrame(animateDragGhost);
}

function endCustomDragGhost() {
  document.removeEventListener('dragover', onDragGhostMove);
  if (_dragGhostState) cancelAnimationFrame(_dragGhostState.raf);
  if (_dragGhost) _dragGhost.remove();
  _dragGhost = null;
  _dragGhostState = null;
}

// Animate a card flying from its on-screen position to the
// hand strip's drop area, then commit it to the hand. Used by
// the deck-tap modal's "Add to hand" button so the player sees
// the card sail from the library / modal to the strip instead
// of it just popping into existence. srcEl is the card element
// inside the modal (or any DOM node we can read a bounding
// rect off); onLand fires AFTER the card has visually arrived.
//
// If we can't find a destination (no hand strip mounted, e.g.
// the player is on a non-browse view) we skip the animation
// and call onLand immediately so callers never block on a
// missing target.
function flyCardToHand(srcEl, card, onLand) {
  const land = () => { try { onLand?.(); } catch (e) { console.error('flyCardToHand land:', e); } };
  const dest = document.getElementById('sandbox-hand-cards')
    || document.getElementById('sandbox-hand');
  if (!srcEl || !dest) { land(); return; }
  const srcRect = srcEl.getBoundingClientRect();
  const dstRect = dest.getBoundingClientRect();
  if (!srcRect.width || !srcRect.height) { land(); return; }
  // Build a clone of the card art, fixed-position it over the
  // source, then transition it toward the hand strip. We use a
  // CSS transition (transform + opacity) because the runtime is
  // simple and the browser can keep the transform on the GPU.
  const ghost = (srcEl.cloneNode(true));
  ghost.classList.add('hand-flight-ghost');
  ghost.style.position = 'fixed';
  ghost.style.left = srcRect.left + 'px';
  ghost.style.top  = srcRect.top + 'px';
  ghost.style.width  = srcRect.width + 'px';
  ghost.style.height = srcRect.height + 'px';
  ghost.style.margin = '0';
  ghost.style.pointerEvents = 'none';
  ghost.style.zIndex = '120';
  ghost.style.transformOrigin = 'top left';
  ghost.style.transform = 'translate(0, 0) scale(1)';
  ghost.style.transition = 'transform 520ms cubic-bezier(0.22, 0.61, 0.36, 1), opacity 520ms ease-out';
  ghost.style.willChange = 'transform, opacity';
  // Land near the LEFT edge of the strip so the card looks
  // like it slots into the first position (cards stack
  // left-to-right; new hand cards appear at the left end of
  // the strip). The final scale (~0.4) matches the hand-
  // strip's visual card size.
  const targetX = dstRect.left + 24;
  const targetY = dstRect.top + (dstRect.height - srcRect.height * 0.4) / 2;
  const dx = targetX - srcRect.left;
  const dy = targetY - srcRect.top;
  document.body.appendChild(ghost);
  // Force layout before the transform change so the transition
  // actually fires (otherwise the browser collapses the two
  // styles and skips animation).
  void ghost.offsetWidth;
  ghost.style.transform = `translate(${dx}px, ${dy}px) scale(0.4) rotate(-6deg)`;
  ghost.style.opacity = '0.05';
  let settled = false;
  const finish = () => {
    if (settled) return;
    settled = true;
    ghost.remove();
    land();
  };
  ghost.addEventListener('transitionend', finish);
  // Safety net in case transitionend doesn't fire (off-screen,
  // tab inactive, prefers-reduced-motion suppressing the
  // transition).
  setTimeout(finish, 700);
}

// Tap modal for a card sitting in the deck. Confirms "add to
// hand" with a single primary action. Mobile-friendly because
// HTML5 drag-and-drop doesn't work reliably on touch; pointing
// + tapping is a more honest gesture for "I want this card."
function openDeckTapModal(card, kind, { allowAuction = false, inspectOnly = false } = {}) {
  const overlay = document.createElement('div');
  overlay.className = 'card-modal-overlay';
  const close = () => overlay.remove();
  overlay.addEventListener('click', (e) => { if (e.target === overlay) close(); });

  const panel = document.createElement('div');
  panel.className = 'card-modal-panel';
  // Corner × close button (top-right of the card).
  const xBtn = document.createElement('button');
  xBtn.type = 'button';
  xBtn.className = 'modal-x';
  xBtn.textContent = '×';
  xBtn.setAttribute('aria-label', 'Close');
  xBtn.addEventListener('click', close);
  panel.appendChild(xBtn);
  const cardEl = renderCard(card, {
    type: kind,
    onSupportClick: (kinds) => {
      close();
      openSupportBrowser(kinds);
    },
  });
  cardEl.classList.add('card-modal-card');
  panel.appendChild(cardEl);

  const actions = document.createElement('div');
  actions.className = 'card-modal-actions';

  // Action button depends on context + mode:
  //   - allowAuction (opened FROM the cart, market mode): a
  //     "🎯 Auction" button that buys this deck-top card.
  //   - market mode, opened from the LIBRARY (no allowAuction):
  //     strictly read-only - no add, no auction. Auctions only
  //     happen in the cart.
  //   - Free Library mode: "✋ Add to hand" + flight.
  const inMarket = getMarketMode() === MARKET_MODE.MARKET;
  if (inspectOnly) {
    // Read-only reference views. Crew enters play only through the
    // starting-crew wizard at New game; GW thrusters are an upcoming
    // expansion you can preview (flip to see both faces) but not yet
    // play. Either way there's no add / auction here.
    const note = document.createElement('p');
    note.className = 'muted card-modal-note';
    note.textContent = isExpansionLocked(card)
      ? '🚧 This is an upcoming expansion card. Preview only for now - flip to see both faces.'
      : '👥 Crew is chosen at New game via the starting-crew wizard.';
    actions.append(note);
  } else if (inMarket && allowAuction) {
    const auctionBtn = document.createElement('button');
    auctionBtn.type = 'button';
    auctionBtn.className = 'modal-btn stack';
    const bonus = supportBonusDecks(card).length;
    auctionBtn.textContent = bonus > 0 ? `🎯 Auction (+${bonus} bonus)` : '🎯 Auction';
    auctionBtn.title = 'Auction this card (1 op, 0 aqua in sandbox mode).';
    auctionBtn.addEventListener('click', () => {
      close();
      doAuctionCard(card);
    });
    actions.append(auctionBtn);
  } else if (inMarket) {
    const note = document.createElement('p');
    note.className = 'muted card-modal-note';
    note.textContent = '🛒 Card Market: patents are acquired from the Cart tab, not the library. This view is read-only.';
    actions.append(note);
  } else {
    const addBtn = document.createElement('button');
    addBtn.type = 'button';
    addBtn.className = 'modal-btn stack';
    addBtn.textContent = '✋ Add to hand';
    addBtn.addEventListener('click', () => {
      // Validate up front: don't fly the animation just to bounce
      // (dup card, expansion card, etc). Surface the reason and
      // skip the flight.
      if (isInHand(card.id)) {
        setStatus(`Can't add: already in your hand.`);
        close();
        return;
      }
      // Close the modal first so the user sees the card take
      // flight against the underlying view, not against a fading
      // backdrop. The flight clones the modal card element so the
      // ghost survives the close.
      const srcEl = cardEl;
      overlay.classList.add('is-flying');
      if (_online) {
        // Land it in the hand NOW (optimistic) and fire BUY_CARD immediately -
        // not from the flight callback - so the op always sends and the card
        // doesn't wait on a round-trip. BUY_CARD is a free action at 0 cost in
        // Free Library; the snapshot reconciles (and reverts + toasts on error).
        addToHand(card);
        submitOnlineOp({ kind: 'BUY_CARD', cardId: card.id, free: true });
        flyCardToHand(srcEl, card, () => {});
      } else {
        flyCardToHand(srcEl, card, () => {
          const r = addToHand(card);
          if (!r.ok) setStatus(`Can't add: ${r.reason}.`);
        });
      }
      // Fade the modal itself out in parallel with the flight so
      // the player's eye follows the card to the strip rather than
      // getting stuck on a still-open dialog.
      overlay.style.transition = 'opacity 220ms ease-out';
      overlay.style.opacity = '0';
      setTimeout(close, 240);
    });
    actions.append(addBtn);
  }

  panel.appendChild(actions);
  overlay.appendChild(panel);
  mountOverlay(overlay);
  // Tap the backdrop or press Escape to dismiss - no explicit ×
  // button. The card modal is small and the backdrop is the
  // obvious affordance.
  const onKey = (e) => { if (e.key === 'Escape') { close(); document.removeEventListener('keydown', onKey); } };
  document.addEventListener('keydown', onKey);
}

// Make a rendered stack card open its read-only close-up modal on click, so a
// player can inspect any card in LEO / the Rocket / an Outpost up close. Guards
// the card's own controls (Flip, support chips, the radiator Light/Heavy
// toggle) so those keep working; a click anywhere else on the card opens the
// big view. `face` opens the modal on the side that's installed in the stack.
function makeCardViewable(cardEl, card, kind, face, nav) {
  if (!cardEl) return cardEl;
  cardEl.classList.add('is-viewable');
  cardEl.title = 'Tap to view this card up close';
  cardEl.addEventListener('click', (e) => {
    if (e.target.closest('button, [role="button"], .rad-side, .card-flip')) return;
    openCardModal(card, kind, null, { readOnly: true, face, nav });
  });
  return cardEl;
}

// Build the swipe-browse sibling list for a stack or the hand. Accepts bare id
// strings (hand) or { id, kind, face } slot objects (LEO / rocket / outpost).
// slotIdx is the position in the list (the hand uses it for per-card actions).
function stackSiblings(list) {
  if (!Array.isArray(list)) return [];
  const out = [];
  for (const s of list) {
    const id = (typeof s === 'string') ? s : (s && s.id);
    if (!id) continue;
    const c = PATENTS_BY_ID[id] || CREW_BY_ID[id];
    if (!c) continue;
    out.push({
      card: c,
      kind: (s && typeof s === 'object' && s.kind) ? s.kind : (CREW_BY_ID[id] ? 'crew' : 'patent'),
      face: (s && typeof s === 'object') ? s.face : undefined,
      slotIdx: out.length,
    });
  }
  return out;
}

// Swipe (touch) + arrow-key + on-screen ‹ › browsing for a card modal whose
// card belongs to a stack / hand. nav = { siblings, index }; navigating closes
// this modal and reopens the sibling, carrying the same list.
function setupCardModalNav(overlay, panel, close, cleanups, nav, { readOnly }) {
  const sibs = nav && Array.isArray(nav.siblings) ? nav.siblings : null;
  const idx = nav ? (nav.index | 0) : -1;
  if (!sibs || sibs.length < 2 || idx < 0) return;
  const go = (dir) => {
    const ni = idx + dir;
    if (ni < 0 || ni >= sibs.length) return;
    const s = sibs[ni];
    if (!s || !s.card) return;
    close();
    openCardModal(s.card, s.kind || 'patent', (s.slotIdx != null ? s.slotIdx : null),
      { readOnly, face: s.face, nav: { siblings: sibs, index: ni } });
  };
  // Touch swipe: left -> next card, right -> previous.
  let sx = 0, sy = 0, st = 0;
  const onTS = (e) => { const t = e.changedTouches[0]; sx = t.clientX; sy = t.clientY; st = Date.now(); };
  const onTE = (e) => {
    const t = e.changedTouches[0];
    const dx = t.clientX - sx, dy = t.clientY - sy;
    if (Date.now() - st < 700 && Math.abs(dx) > 48 && Math.abs(dx) > Math.abs(dy) * 1.4) go(dx < 0 ? 1 : -1);
  };
  overlay.addEventListener('touchstart', onTS, { passive: true });
  overlay.addEventListener('touchend', onTE, { passive: true });
  cleanups.push(() => { overlay.removeEventListener('touchstart', onTS); overlay.removeEventListener('touchend', onTE); });
  // Arrow keys.
  const onArrow = (e) => {
    if (e.key === 'ArrowLeft') { e.preventDefault(); go(-1); }
    else if (e.key === 'ArrowRight') { e.preventDefault(); go(1); }
  };
  document.addEventListener('keydown', onArrow);
  cleanups.push(() => document.removeEventListener('keydown', onArrow));
  // On-screen control (surfaces the browse on desktop too).
  const bar = document.createElement('div');
  bar.className = 'card-modal-nav';
  const prev = document.createElement('button');
  prev.type = 'button'; prev.className = 'card-modal-arrow'; prev.textContent = '‹';
  prev.setAttribute('aria-label', 'Previous card'); prev.disabled = idx <= 0;
  prev.addEventListener('click', () => go(-1));
  const pos = document.createElement('span');
  pos.className = 'card-modal-pos'; pos.textContent = `${idx + 1} / ${sibs.length}`;
  const next = document.createElement('button');
  next.type = 'button'; next.className = 'card-modal-arrow'; next.textContent = '›';
  next.setAttribute('aria-label', 'Next card'); next.disabled = idx >= sibs.length - 1;
  next.addEventListener('click', () => go(1));
  bar.append(prev, pos, next);
  overlay.appendChild(bar);
}

// Inspect modal: enlarged copy of the clicked card with three
// actions - Discard (pop back to the deck), Exo produce (will
// need a factory location once Stage-3 builds them), and Add to
// stack (push onto the LEO rocket).
function openCardModal(card, kind, slotIdx, { readOnly = false, face, radSide, nav } = {}) {
  const overlay = document.createElement('div');
  overlay.className = 'card-modal-overlay';
  // Teardown registry: the corner ×, Esc, and any swipe / arrow-key
  // listeners all unhook here, so swipe-browsing to a sibling card leaves
  // nothing dangling behind the reopened modal.
  const cleanups = [];
  const close = () => {
    for (const fn of cleanups) { try { fn(); } catch (e) {} }
    overlay.remove();
  };
  overlay.addEventListener('click', (e) => { if (e.target === overlay) close(); });
  const onKey = (e) => { if (e.key === 'Escape') close(); };
  document.addEventListener('keydown', onKey);
  cleanups.push(() => document.removeEventListener('keydown', onKey));

  const panel = document.createElement('div');
  panel.className = 'card-modal-panel';
  // Corner × close button (top-right of the card). The backdrop tap + Esc
  // still dismiss too; this is the obvious affordance on touch, where the
  // backdrop can be a tight target around a big card.
  const xBtn = document.createElement('button');
  xBtn.type = 'button';
  xBtn.className = 'modal-x';
  xBtn.textContent = '×';
  xBtn.setAttribute('aria-label', 'Close');
  xBtn.addEventListener('click', close);
  panel.appendChild(xBtn);
  const cardEl = renderCard(card, {
    type: kind,
    // Open on the explicitly requested face (e.g. the side installed in a
    // stack), else the picked crew face, else the default primary.
    face: face !== undefined
      ? face
      : (getPickedCrew()?.cardId === card.id ? getPickedCrew()?.face : undefined),
    radSide,   // installed radiator side (heavy/light); undefined -> renderCard's default
    onSupportClick: (kinds) => {
      close();
      openSupportBrowser(kinds);
    },
  });
  cardEl.classList.add('card-modal-card');
  panel.appendChild(cardEl);

  // Mount + wire swipe / arrow-key / on-screen browsing (only when the card
  // belongs to a stack or the hand, via nav). Shared by all three exits.
  const mount = () => {
    overlay.appendChild(panel);
    mountOverlay(overlay);
    setupCardModalNav(overlay, panel, close, cleanups, nav, { readOnly });
  };

  // Read-only inspection (e.g. the All cards overview): show the card and its
  // Flip, but NONE of the act-on-card buttons (Discard / Free Market / Exo /
  // Boost).
  if (readOnly) {
    mount();
    return;
  }

  const actions = document.createElement('div');
  actions.className = 'card-modal-actions';

  // Crew has NO per-card actions (no Discard / Sell / Exo-produce
  // / Boost / Flip). Crew never enters the hand and can ONLY move
  // stack-to-stack (LEO <-> rocket <-> outpost) via the stack
  // inspector's transfer controls. Show a note and stop here.
  if (kind === 'crew') {
    const note = document.createElement('p');
    note.className = 'muted card-modal-note';
    note.textContent = '👥 Crew can only be transferred between stacks (LEO ↔ rocket ↔ outpost). It has no hand actions.';
    actions.append(note);
    panel.appendChild(actions);
    mount();
    return;
  }

  // Four primary actions, emoji-led for the quick-icon row on
  // hand-slot hover (defined further down) to mirror the same
  // verbs. Boost flags the card for the next BOOST commit;
  // the commit lives on the hand strip's BOOST button (lit
  // when at least one card is marked).
  // Discard: voluntary free action, 1/turn, sends the Hand
  // card to the bottom of its corresponding patent deck (user,
  // 2026-05-24: "you can discard a card from your hand at a
  // ny time, 1 per turn, that goes to the back of the deck").
  // Crew cards don't have a deck to return to in this slice -
  // they just leave the hand. Per-turn budget tracked in
  // turn-clock.js.
  const discardBtn = document.createElement('button');
  discardBtn.type = 'button';
  discardBtn.className = 'modal-btn discard';
  discardBtn.textContent = '🗑 Discard';
  discardBtn.title = `Send this card to the bottom of the ${card.type || 'corresponding'} deck. Free action, any number per turn.`;
  // Shared discard path (online routes the DISCARD server op so it
  // persists; solo mutates locally). Same helper the hand quick-action
  // trash icon uses, so the two can't drift.
  discardBtn.addEventListener('click', () => {
    if (discardBtn.disabled) return;
    discardHandCard(card, slotIdx, close);
  });

  const sellBtn = document.createElement('button');
  sellBtn.type = 'button';
  sellBtn.className = 'modal-btn sell';
  sellBtn.textContent = '💱 Free Market';
  sellBtn.title = `Free Market: effectively sells this card to gain $${FREE_MARKET_AQUA}, returning it to the bottom of its deck. Costs 1 operation.`;
  sellBtn.addEventListener('click', () => {
    freeMarketSellFromHand(card, close);
  });

  const produceBtn = document.createElement('button');
  produceBtn.type = 'button';
  produceBtn.className = 'modal-btn produce';
  // ET / Exo produce: flip this hand card Black-Side-up into an
  // outpost at a colocated factory whose spectral type matches the
  // card. Same op as the site-popup "ET Produce", just driven from
  // the card. Gated on the rocket being parked at a matching,
  // player-owned factory with outpost room; greyed-out + explained
  // otherwise.
  const cardSpectral = card.spectralType || 'C';
  const exoFreeSlots = getAvailableOutpostSlots();
  // ET / Exo produce targets a factory the player OWNS whose spectral matches
  // this card - the rocket need NOT be parked there (the factory does the
  // producing). Candidate sites: where the rocket sits, plus every site that
  // already holds one of the player's outposts. The first one with a matching
  // owned factory (and outpost room) wins; a site's own ET Produce button stays
  // the way to pick a specific site or open a fresh outpost from nothing.
  let exoSite = null, exoFactory = null, exoOutposts = [];
  if (kind !== 'crew') {
    const seen = new Set();
    const candidates = [];
    const rocketSite = getRocketSite();
    if (rocketSite) { candidates.push(rocketSite); seen.add(rocketSite.id); }
    for (const o of Object.values(getOutposts())) {
      if (o.siteId && !seen.has(o.siteId)) {
        seen.add(o.siteId);
        const s = SITES_BY_ID[o.siteId];
        if (s) candidates.push(s);
      }
    }
    for (const s of candidates) {
      const f = getFactory(s.id);
      if (!f || !iCanUseFactory(f) || !spectralProducibleAt(cardSpectral, f.spectralType)) continue;
      const outpostsHere = Object.values(getOutposts()).filter((o) => o.siteId === s.id);
      if (outpostsHere.length > 0 || exoFreeSlots.length > 0) {
        exoSite = s; exoFactory = f; exoOutposts = outpostsHere;
        break;
      }
    }
  }
  const canExo = !!(exoSite && exoFactory);
  produceBtn.textContent = `🏭 Exo produce (${cardSpectral})`;
  produceBtn.disabled = !canExo;
  produceBtn.title = canExo
    ? `Produce this card Black-Side-up into a factory at ${exoSite.name} (spectral ${cardSpectral}).`
    : `Need a factory you own with spectral ${cardSpectral} plus an outpost there (or a free outpost slot). Use a site's ET Produce to pick the spot, or industrialize one first.`;
  produceBtn.addEventListener('click', () => {
    if (!canExo) return;
    close();
    doEtProduce(exoSite, exoFactory,
      [{ id: card.id, card, name: card.name }], exoOutposts, exoFreeSlots);
  });

  const boostBtn = document.createElement('button');
  boostBtn.type = 'button';
  boostBtn.className = 'modal-btn stack';
  const marked = isBoostMarked(card.id);
  const boostable = isBoostable(card);
  boostBtn.textContent = marked ? '🚀 Unmark boost' : '🚀 Boost';
  boostBtn.disabled = !boostable;
  boostBtn.title = !boostable
    ? BOOST_BLOCKED_MSG
    : (marked
      ? 'Remove the boost mark on this card'
      : 'Mark this card to be boosted to the LEO rocket on the next BOOST commit');
  boostBtn.addEventListener('click', () => {
    if (boostBtn.disabled) return;
    toggleBoostMark(card.id);
    close();
  });

  actions.append(discardBtn, sellBtn, produceBtn, boostBtn);
  panel.appendChild(actions);
  mount();
}

// Side panel: a vertical tab strip on the right edge of the
// browse view. Each tab pops a different pane in/out. Clicking the
// active tab closes the panel; clicking the × close button does
// the same. Pane content (patents / milestones / events) is
// rendered lazily on first open and then left mounted.
function wireSidebar() {
  if (_sidebarWired) return;
  _sidebarWired = true;
  const panel = document.getElementById('browse-sidepanel');
  const tabs  = document.getElementById('sidepanel-tabs');
  const close = document.getElementById('sidepanel-close');
  if (!panel || !tabs || !close) return;

  for (const btn of tabs.querySelectorAll('button')) {
    // Swap the placeholder emoji for the custom icon (keeps title / aria-label /
    // hidden attrs; the unread badge is CSS, so innerHTML is safe to set).
    const iconName = btn.id === 'sidepanel-search' ? 'search'
      : btn.id === 'sidepanel-config' ? 'config'
        : btn.dataset.pane;
    const ico = iconName && uiIcon(iconName);
    if (ico) btn.innerHTML = ico;
    // The 🔍 search button isn't a pane - it opens the search modal.
    if (btn.id === 'sidepanel-search') {
      btn.addEventListener('click', () => { _openMapSearch?.(); });
      continue;
    }
    // The ⚙ config button isn't a pane - it opens the config modal.
    if (btn.id === 'sidepanel-config') {
      btn.addEventListener('click', () => openConfigModal());
      continue;
    }
    btn.addEventListener('click', () => {
      const pane = btn.dataset.pane;
      if (panel.dataset.active === pane) {
        // Toggle off if already active.
        showPane(null);
      } else {
        showPane(pane);
      }
    });
  }
  close.addEventListener('click', () => showPane(null));

  // Modal backdrop on mobile: tapping the dimmed area closes the
  // open pane. Backdrop is hidden on desktop via CSS so this is a
  // no-op there.
  const backdrop = document.getElementById('browse-modal-backdrop');
  if (backdrop) backdrop.addEventListener('click', () => showPane(null));
}

function showPane(pane) {
  const panel = document.getElementById('browse-sidepanel');
  if (!panel) return;
  panel.dataset.active = pane || '';
  for (const btn of panel.querySelectorAll('.sidepanel-tabs button')) {
    btn.classList.toggle('active', btn.dataset.pane === pane);
  }
  // Re-tint the politics tab icon's outline for its new selected state.
  updateAssemblyTabIcon(_onlineSnapshot);
  for (const el of panel.querySelectorAll('.panel-pane')) {
    el.classList.toggle('active', el.dataset.pane === pane);
  }
  // Backdrop tracks panel state - visible whenever a pane is open
  // (CSS gates it behind the mobile breakpoint so desktop never
  // sees it).
  const backdrop = document.getElementById('browse-modal-backdrop');
  if (backdrop) backdrop.classList.toggle('hidden', !pane);
  // Render the pane lazily on first reveal.
  if      (pane === 'patents')    renderPatents();
  else if (pane === 'cart')       renderCart();
  else if (pane === 'milestones') renderMilestones();
  else if (pane === 'log')        renderMissionLog();
  else if (pane === 'solo')       renderSolo();
  else if (pane === 'colonists')  renderColonists();
  else if (pane === 'mp')         renderMpPanel(_onlineSnapshot);
  // Opening the table pane clears the "new chat" pulse.
  if (pane === 'mp') clearMpChatUnread();
}

// Float a "+N" aqua indicator above the balance chip, then remove it
// once the CSS rise-and-fade animation ends. Purely cosmetic feedback
// for a credited sale / income.
function spawnAquaGainFloat(anchor, delta) {
  if (!anchor || delta <= 0) return;
  const float = document.createElement('span');
  float.className = 'aqua-gain-float';
  float.textContent = `+${delta}`;
  anchor.appendChild(float);
  float.addEventListener('animationend', () => float.remove());
  // Safety net in case animationend doesn't fire (reduced-motion etc).
  setTimeout(() => float.remove(), 1500);
}

// Route state: shared across renderer instances. Tapping the first
// site sets `from`, tapping the second sets `to` and triggers the
// pathfinder; tapping again starts a new route from that site.
let _routeFrom = null;     // origin once a route has been plotted
let _routeTo = null;       // destination once a route has been plotted
let _selectedId = null;    // currently-highlighted site (just info, no routing)
let _routingMode = false;  // true while the user is picking a destination
let _activeData = null;

// Rocket position state. The sandbox rocket sprite is drawn at
// whichever site the rocket currently occupies; defaults to LEO
// when no id is stored. Persisted so a reload doesn't teleport
// the rocket back to LEO mid-journey. _plannedRoute mirrors the
// segments most recently passed to the renderer so moveRocket()
// can consume them turn-by-turn, and _moveSnapshot lets the 🛸
// toggle's undo restore the previous position + route.
const STORAGE_ROCKET_SITE  = 'hf-sandbox-rocket-site';
const STORAGE_ROCKET_TRAIL = 'hf-sandbox-rocket-trail';
const STORAGE_ROCKET_ROUTE = 'hf-sandbox-planned-route';
const STORAGE_FREIGHTER_ROUTE = 'hf-sandbox-planned-route-freighter';
const STORAGE_BERNAL_ROUTE = 'hf-sandbox-planned-route-bernal';
// Which vehicle the CURRENT _plannedRoute belongs to ('rocket' | 'freighter' |
// 'bernal0' | 'bernal1'). Each vehicle keeps its OWN persisted plan (separate
// localStorage key + a separate server-side route) so plotting one never
// overwrites the other.
let _plannedRouteUnit = 'rocket';
// Which vehicle the "Plan move" combo + the toolbar move-points dropdown act on.
// Shared by both controls so picking a vehicle in one selects it in the other.
let _selectedMoveUnit = 'rocket';
function routeStorageKey(unit) {
  const u = unit || _plannedRouteUnit;
  if (u === 'freighter') return STORAGE_FREIGHTER_ROUTE;
  if (typeof u === 'string' && u.startsWith('bernal')) return `${STORAGE_BERNAL_ROUTE}-${u.slice('bernal'.length)}`;
  return STORAGE_ROCKET_ROUTE;
}
// M1 Mobile Factory fleet (1B6): the factory currently being plotted (server
// siteId) and the per-factory planned routes, keyed by server siteId. Each
// factory plots like the freighter (1 burn/turn); the shared Move-fleet button
// fires them all at once via MOVE_FLEET. In-memory only (a turn-local plan).
let _plannedFactoryId = null;
let _factoryRoutes = {};
// Pre-move snapshot written while a (possibly hazardous) move is
// being resolved. If the tab is closed / refreshed mid-resolution
// the queue is abandoned, so on the next load we roll the move back
// to this snapshot (refunding the move + fuel) rather than stranding
// the player with a spent turn. Cleared at every move exit path.
const STORAGE_PENDING_MOVE = 'hf-sandbox-pending-move';
const STORAGE_ROUTE_PRIORITY = 'hf-sandbox-route-priority';
// One-time flag: the default flipped from turns-first to burns-first. On first
// load after that change we force burns-first for EVERYONE (including users who
// had the old turns-first saved), then respect whatever they pick afterwards.
const STORAGE_ROUTE_PRIORITY_BURNS_DEFAULT = 'hf-route-priority-burns-default';
// Routing metric priority. 'turns' minimizes turn-ends first (the
// snap-to-adjacent default); 'burns' minimizes water spend first
// (favours long Hohmann coasts at the cost of more turns). User-
// togglable via the ⚙ gear in the site popup; persisted so the
// pick survives reloads.
let _routePriority = (() => {
  try {
    // One-time force to burns-first (overrides an old saved turns-first), then
    // respect the player's choice on later loads.
    if (!localStorage.getItem(STORAGE_ROUTE_PRIORITY_BURNS_DEFAULT)) {
      localStorage.setItem(STORAGE_ROUTE_PRIORITY_BURNS_DEFAULT, '1');
      localStorage.setItem(STORAGE_ROUTE_PRIORITY, 'burns');
      return 'burns';
    }
    const s = localStorage.getItem(STORAGE_ROUTE_PRIORITY);
    return s === 'burns' || s === 'turns' ? s : 'burns';
  } catch { return 'burns'; }
})();
function setRoutePriority(mode) {
  if (mode !== 'turns' && mode !== 'burns') return;
  _routePriority = mode;
  try { localStorage.setItem(STORAGE_ROUTE_PRIORITY, mode); } catch {}
}
// Avoid-hazards / avoid-radiation planner toggles. These are INDEPENDENT: a
// player can route around generic hazard burns (the skull / aerobrake rolls)
// while still flying straight through radiation belts, or the reverse. When a
// toggle is ON the planner treats that hazard class as the dominant cost,
// routing around it even at the price of extra burns / turns. Persisted per
// device. Avoid-hazards defaults ON; avoid-radiation defaults OFF (a confident
// player flies through radiation unless they opt in).
const STORAGE_ROUTE_AVOID_HAZARDS = 'hf-sandbox-route-avoid-hazards';
const STORAGE_ROUTE_AVOID_RADIATION = 'hf-sandbox-route-avoid-radiation';
let _routeAvoidHazards = (() => {
  try {
    const v = localStorage.getItem(STORAGE_ROUTE_AVOID_HAZARDS);
    return v === null ? true : v === '1';   // absent -> default ON
  } catch { return true; }
})();
let _routeAvoidRadiation = (() => {
  try { return localStorage.getItem(STORAGE_ROUTE_AVOID_RADIATION) === '1'; }
  catch { return false; }
})();
function setRouteAvoidHazards(on) {
  _routeAvoidHazards = !!on;
  try { localStorage.setItem(STORAGE_ROUTE_AVOID_HAZARDS, on ? '1' : '0'); } catch {}
}
function setRouteAvoidRadiation(on) {
  _routeAvoidRadiation = !!on;
  try { localStorage.setItem(STORAGE_ROUTE_AVOID_RADIATION, on ? '1' : '0'); } catch {}
}
function routeMetricPriority() {
  const base = _routePriority === 'burns' ? ['burns', 'turns'] : ['turns', 'burns'];
  // The planner compares these metrics lexicographically, so the FIRST entry is
  // the one it minimizes hardest. Each AVOIDED hazard class leads the base
  // metrics (any crossing outweighs any number of burns or turns); an
  // un-avoided class stays the final tiebreaker, the old behaviour. Generic
  // hazards lead radiation when both are avoided, preserving prior ordering.
  const lead = [];
  const tail = [];
  (_routeAvoidHazards ? lead : tail).push('hazards');
  (_routeAvoidRadiation ? lead : tail).push('radHazards');
  return [...lead, ...base, ...tail];
}

// Manual move mode. Alternative to the auto-planner: the player
// taps neighbouring sites one at a time to build a route by
// hand. Burn budget = active thruster's `thrust` value. Each
// hop's cost obeys the rulebook's Hohmann + pivot rules:
//
//   - Entering a non-burn node (Hohmann, lagrange, site, radhaz,
//     venus, decorative) → 0 burns. They're "free" stops.
//   - Entering a burn node → its `landing` value (default 1,
//     half-landers cost 2 the second time).
//   - Pivoting at a Hohmann (changing direction at a labelled
//     edge node) → +1 burn. Pivots are FREE up to the mover's
//     Bonus Pivot count (N): a pirouette thruster's `bonusPivots`
//     for the rocket (or the freighter card's, for the freighter).
//     All N are free, not just the first.
//
// Each manual hop becomes a turn-1 segment in _plannedRoute;
// once the player hits Move the existing moveRocket flow consumes
// them all in one animation. Cancel = clear route. Fuel is not
// deducted (sandbox mode treats burns as free per the current
// rules); thrust is just the planning budget.
let _manualMode = false;
let _manualBudget = 0;
let _manualBudgetMax = 0;
let _manualOriginId = null;
let _manualDir = null;          // direction we entered the tip on
let _manualPivotsUsed = 0;
let _manualPirouettes = 0;      // free pivots remaining (bonusPivots)
let _manualBonus = 0;           // banked gravity-assist / slingshot credit
let _manualUnit = 'rocket';     // which mover this route drives: 'rocket' | 'freighter'
// Solo manual travel: each hop slides the rocket sprite forward one segment so
// the player watches the ship advance one segment at a time as they plot. The
// state isn't committed until Move (one move per turn), so the commit animation
// is then snapped (_fastMoveAnim) to avoid re-flying a route already walked.
let _manualPreviewed = false;
let _fastMoveAnim = false;
function manualTipId() {
  if (_plannedRoute && _plannedRoute.length) {
    return _plannedRoute[_plannedRoute.length - 1].to;
  }
  return _manualOriginId;
}
function activeThrusterBonusPivots() {
  // Read off the active thruster's INSTALLED face (via the shared stats),
  // not faces.primary: a dark-side pirouette thruster like the Dual-Stage
  // 4-Grid carries its bonus on its Tier-2 face, so the primary-face read
  // missed it and the planner never discounted the pivots.
  const stats = getActiveThrusterStats();
  return stats ? (Number(stats.bonusPivots) || 0) : 0;
}
// Free pivots the player's Freighter unit carries (the Bonus Pivots icon count
// on its INSTALLED face). Mirrors freighterCargoLimit's installed-face read.
function freighterBonusPivots() {
  const fr = getMyFreighter();
  if (!fr) return 0;
  const card = cardById(fr.cardId);
  if (!card) return 0;
  const face = fr.face === 'primary' ? 'primary' : 'secondary';
  const fd = card.faces && card.faces[face];
  if (fd && fd.bonusPivots != null) return fd.bonusPivots | 0;
  return (card.bonusPivots | 0) || 0;
}
// Enter the manual route plotter. opts.unit selects the mover:
//   'rocket'    (default) - budget = active thruster thrust, pivots = thruster
//                 bonusPivots, origin = the rocket's site. Unchanged behaviour.
//   'freighter' - the M1 big cube rides the SAME plotter: budget = 1 burn space
//                 per turn (the freighter's propulsion model), pivots = the
//                 freighter card's Bonus Pivots (N), origin = the freighter's
//                 site. The route commits as a MOVE with unit:'freighter'.
function enterManualMoveMode(opts = {}) {
  const unit = (opts.unit === 'freighter' || opts.unit === 'factory') ? opts.unit : 'rocket';
  _manualUnit = unit;
  _plannedRouteUnit = unit;   // this plot belongs to the chosen vehicle
  _plannedFactoryId = unit === 'factory' ? (opts.factoryId || null) : null;
  _routeFrom = null;
  _routeTo = null;
  _plannedRoute = null;
  persistPlannedRoute();
  _manualMode = true;
  _manualDir = null;
  _manualPivotsUsed = 0;
  _manualBonus = 0;
  if (unit === 'freighter' || unit === 'factory') {
    // A freighter / Mobile Factory moves at most one burn space per turn (no
    // thrust/isp/fuel) and uses the Freighter card's Bonus Pivots (1B6a).
    _manualBudget = 1;
    _manualBudgetMax = 1;
    _manualPirouettes = freighterBonusPivots();
    _manualOriginId = unit === 'factory' ? (opts.originPlannerId || null) : getStackSiteId('freighter');
  } else {
    const thrStats = getActiveThrusterStats();
    const thrust = thrStats && Number.isFinite(thrStats.thrust) ? thrStats.thrust : 4;
    _manualBudget = thrust;
    _manualBudgetMax = thrust;
    _manualPirouettes = activeThrusterBonusPivots();
    const here = getRocketSite();
    _manualOriginId = here ? here.id : null;
  }
  _plannedRoute = [];
  persistPlannedRoute();
  if (_renderer) {
    _renderer.setRoute(null);
    if (typeof _renderer.setRouteUnit === 'function') _renderer.setRouteUnit(unit);  // freighter route = green
    _renderer.setRouteEndpoints(_manualOriginId, _manualOriginId);
    // Make route waypoints (hohmann / lagrange / burn) tappable so the player
    // can plot INTO a Hohmann transfer, not just between landable sites.
    _renderer.setRoutingHit(true);
  }
  const clearBtn = document.getElementById('route-clear');
  if (clearBtn) { clearBtn.hidden = false; clearBtn.textContent = '✕ Stop'; }
  updateManualGlow();
  manualMoveStatus();
}
function exitManualMoveMode() {
  _manualMode = false;
  _manualUnit = 'rocket';
  _manualBudget = 0;
  _manualBudgetMax = 0;
  _manualOriginId = null;
  _manualDir = null;
  _manualPivotsUsed = 0;
  _manualPirouettes = 0;
  _manualBonus = 0;
  // Per-hop preview may have walked the sprite forward; if the player bailed
  // without committing a move, snap it back to the real rocket position.
  // (On a committed move moveRocket has already cleared _manualPreviewed, so
  // this leaves the ship at its new site.)
  const previewed = _manualPreviewed;
  _manualPreviewed = false;
  if (_renderer) {
    _renderer.setRoutingHit(false);
    _renderer.setMoveTargets(null);
    if (previewed && !_rocketAnimating) syncSandboxRocket();
  }
  setManualBurnBadge(null);
  const clearBtn = document.getElementById('route-clear');
  if (clearBtn) clearBtn.textContent = 'Clear route';
}
function manualMoveStatus() {
  if (!_manualMode) return;
  let planned = 0;
  if (_plannedRoute) for (const s of _plannedRoute) planned += (s.burns || 0);
  const pirouetteHint = _manualPirouettes > 0
    ? ` <em class="muted">(${_manualPirouettes} free pivot${_manualPirouettes === 1 ? '' : 's'} ready)</em>`
    : '';
  const flybyHint = _manualBonus > 0
    ? ` <em class="muted">(+${_manualBonus} swing-by credit banked)</em>`
    : '';
  const burnTag = `<strong>${planned}</strong> burn${planned === 1 ? '' : 's'} plotted`;
  if (_manualBudget <= 0) {
    setStatus(`✋ Manual: ${burnTag}, <strong>0</strong>/${_manualBudgetMax} burns left.${flybyHint} Tap <strong>🛸 Move</strong> to fly, or <strong>✕ Stop</strong>.`);
  } else {
    setStatus(`✋ Manual: ${burnTag}, <strong>${_manualBudget}</strong>/${_manualBudgetMax} burns left.${pirouetteHint}${flybyHint} Tap a glowing node to advance one hop. <strong>🛸 Move</strong> to fly, <strong>✕ Stop</strong> to cancel.`);
  }
}
// Contracted "tap target" adjacency. The planner graph threads degree-2
// DECORATIVE bend nodes between the real nodes (a Hohmann dot connects to
// the next site only THROUGH a chain of invisible decoratives). Decoratives
// are excluded from the click hit-test, so a plain direct-neighbour check
// reported a visually-adjacent node as "not adjacent". This walks outward
// from `tipId` THROUGH decorative nodes only and returns the first real
// (non-decorative) node reached on each branch, along with the underlying
// path so the hop can render + animate along the curve. Memoised per tip
// since the map graph is static for the session.
let _meaningfulNbrCache = null;   // Map<tipId, Array<{ id, path }>>
function meaningfulNeighbors(tipId) {
  if (!_activeData || !tipId) return [];
  if (!_meaningfulNbrCache) _meaningfulNbrCache = new Map();
  if (_meaningfulNbrCache.has(tipId)) return _meaningfulNbrCache.get(tipId);
  const points = _activeData.byId || {};
  const neighbors = _activeData.neighbors;
  const isDeco = (id) => {
    const p = points[id];
    return !!p && (p.isDecorative || p.type === 'decorative');
  };
  const out = [];
  const found = new Set();
  const visitedDeco = new Set();
  const stack = [];
  for (const n of (neighbors && neighbors.get(tipId)) || []) {
    stack.push({ node: n, path: [tipId, n] });
  }
  while (stack.length) {
    const { node, path } = stack.pop();
    if (!points[node]) continue;
    if (isDeco(node)) {
      if (visitedDeco.has(node)) continue;
      visitedDeco.add(node);
      for (const nn of (neighbors && neighbors.get(node)) || []) {
        if (nn === tipId || path.includes(nn)) continue;
        stack.push({ node: nn, path: [...path, nn] });
      }
    } else if (!found.has(node)) {
      found.add(node);
      out.push({ id: node, path });
    }
  }
  _meaningfulNbrCache.set(tipId, out);
  return out;
}

// Gravity-assist / slingshot credit a node grants when entered. Mirror of the
// auto-planner's flybyBoost handling (planner-nav.js#getNeighbors): a Lagrange
// swing-by (and, seasonally, a Venus flyby) banks a bonus that offsets later
// burn + pivot costs. 'thrust' resolves to the active thruster's thrust. Venus
// is gated OFF here to match the auto-planner, which builds with the default
// 'red' season; the Lagrange rings always credit.
function nodeFlybyBoost(node) {
  if (!node) return 0;
  const venusFlybyAvailable = false; // auto-planner default season is 'red'
  const raw = (node.type === 'venus' && !venusFlybyAvailable) ? 0 : (node.flybyBoost ?? 0);
  return raw === 'thrust' ? (_manualBudgetMax || 0) : (Number(raw) || 0);
}
